  [653788] = "{id=653788,Text='以身为盾，至死不悔。',Speaker=816544,Option='我来转职',ModelFace=1,ModelAct=867,}",
  [653789] = "{id=653789,Text='皇家卫士使用长枪和盾牌战斗，又被誉为“团队之盾”，是屹立在魔物和队友间最坚硬的壁垒。',Speaker=816544,ModelFace=1,ModelAct=867,}",
