  [653897] = "{id=653897,Text='你已经拥有成为进阶初心者和忍者的资格，你确定要转职为弓箭手吗？',Speaker=816550,Option='{我确定,2},{我再想想,101}',}",
  [653898] = "{id=653898,Text='星辰祝福我的箭矢，因而我百发百中。',Speaker=816550,Option='我来转职',}",
  [653899] = "{id=653899,Text='游侠可以驾驭魔狼，以精良的射术和多种陷阱制造伤害或者干扰敌人，讲究策略、身法轻灵。',Speaker=816550,}",
  [653900] = "{id=653900,Text='你确定要将游侠作为自己的职业目标吗？',Speaker=816550,Option='{确定,100},{再考虑一下,101}',}",
  [653901] = "{id=653901,Text='可以，拿定主意后，可以再来找我。',Speaker=816550,}",
  [653902] = "{id=653902,Text='好，那我现在就为你转职成弓箭手。',Speaker=816550,Action={actionid=203},}",
  [653903] = "{id=653903,Text='平心静气，摒弃所有的杂念。',Speaker=811915,ModelFace=1,ModelAct=8,}",
  [653904] = "{id=653904,Text='将意志注入誓言之书，获得它的承认。',Speaker=816550,}",
  [653905] = "{id=653905,Text='恭喜你踏上成为游侠的道路。',Speaker=816550,}",
  [653906] = "{id=653906,Text='愿星光始终指引你的脚步。',Speaker=816550,}",
  [653907] = "{id=653907,Text='你已经拥有成为进阶初心者和忍者的资格，你确定要转职为弓箭手吗？',Speaker=816566,Option='{我确定,2},{我再想想,101}',ModelFace=1,ModelAct=867,}",
  [653908] = "{id=653908,Text='我曾经历风雨，仍旧初心不泯。',Speaker=816566,Option='我来转职',ModelFace=1,ModelAct=867,}",
  [653909] = "{id=653909,Text='想成为进阶初心者，就必须始终保持初心。【若选择成为进阶初心者，玩家必须保持初心者职业到base lv80才能接取转职任务。base lv80前可接取其他职业转职任务。】',Speaker=816566,ModelFace=1,ModelAct=867,}",
  [653910] = "{id=653910,Text='你确定要将进阶初心者作为自己的职业目标吗？',Speaker=816566,Option='{确定,100},{再考虑一下,101}',ModelFace=1,ModelAct=867,}",
  [653911] = "{id=653911,Text='我能理解，毕竟坚守初心并不是一件简单的事情。',Speaker=816566,ModelFace=1,ModelAct=867,}",
  [653912] = "{id=653912,Text='好，那我现在就为你转职成弓箭手。',Speaker=816566,ModelFace=1,ModelAct=867,Action={actionid=203},}",
  [653913] = "{id=653913,Text='平心静气，摒弃所有的杂念。',Speaker=811915,ModelFace=1,ModelAct=8,}",
  [653914] = "{id=653914,Text='将意志注入誓言之书，获得它的承认。',Speaker=816566,ModelFace=1,ModelAct=867,}",
  [653915] = "{id=653915,Text='好，那你就继续保持初心者的职业吧。',Speaker=816566,ModelFace=1,ModelAct=867,}",
  [653916] = "{id=653916,Text='守护初心确实是个困难的选择，但相信我，它会有回报的。',Speaker=816566,ModelFace=1,ModelAct=867,}",
  [653917] = "{id=653917,Text='我之魂灵仿佛浪花，纵开一瞬即是永恒。',Speaker=816567,Option='{我确定,2},{我再想想,101}',ModelFace=1,ModelAct=763,}",
  [653918] = "{id=653918,Text='我之魂灵仿佛浪花，纵开一瞬即是永恒。',Speaker=816567,Option='我来转职',ModelFace=1,ModelAct=763,}",
  [653919] = "{id=653919,Text='影狼可以为团队提供辅助，干扰、控制敌人；也可以使用影分身，造成爆发伤害。',Speaker=816567,ModelFace=1,ModelAct=763,}",
  [653920] = "{id=653920,Text='你确定要将影狼作为自己的职业目标吗？',Speaker=816567,Option='{确定,100},{再考虑一下,101}',ModelFace=1,ModelAct=763,}",
  [653921] = "{id=653921,Text='心中还有迷茫吗？那么就等你意志坚定后再来找我吧。',Speaker=816567,ModelFace=1,ModelAct=763,}",
  [653922] = "{id=653922,Text='好，那我现在就为你转职成忍者。',Speaker=816567,ModelFace=1,ModelAct=763,Action={actionid=203},}",
  [653923] = "{id=653923,Text='平心静气，摒弃所有的杂念。',Speaker=811915,ModelFace=1,ModelAct=8,}",
  [653924] = "{id=653924,Text='好，那你就继续保持初心者的职业吧。',Speaker=816567,ModelFace=1,ModelAct=763,}",
  [653925] = "{id=653925,Text='所谓忍者，是能驾驭自身内部“魂”的强者。',Speaker=816567,ModelFace=1,ModelAct=763,}",
  [653926] = "{id=653926,Text='年轻人，修身之余，也要记得修心。',Speaker=816567,ModelFace=1,ModelAct=763,}",
  [653927] = "{id=653927,Text='胧可以为团队提供辅助，干扰、控制敌人；也可以使用影分身，造成爆发伤害。',Speaker=816567,ModelFace=1,ModelAct=763,}",
  [653928] = "{id=653928,Text='你确定要将胧作为自己的职业目标吗？',Speaker=816567,Option='{确定,100},{再考虑一下,101}',ModelFace=1,ModelAct=763,}",
  [653929] = "{id=653929,Text='你已经拥有成为进阶初心者和忍者的资格，你确定要转职为弓箭手吗？',Speaker=816564,Option='{我确定,2},{我再想想,101}',ModelFace=1,ModelAct=867,}",
  [653930] = "{id=653930,Text='小猫咪~很高兴可以在这里见到你喵。',Speaker=816564,Option='我来转职',ModelFace=1,ModelAct=867,}",
  [653931] = "{id=653931,Text='唤灵者是我们多兰族独有的职业，喵呜。讲究与万物和平共生，利用自然之力作战。',Speaker=816564,ModelFace=1,ModelAct=867,}",
  [653932] = "{id=653932,Text='你确定要将唤灵者作为自己的职业目标吗？',Speaker=816564,Option='{确定,100},{再考虑一下,101}',ModelFace=1,ModelAct=867,}",
  [653933] = "{id=653933,Text='嗯嗯，想清楚了可以再来找我喵。',Speaker=816564,ModelFace=1,ModelAct=867,}",
  [653934] = "{id=653934,Text='好，那我现在就为你转职成术士。',Speaker=816564,ModelFace=1,ModelAct=867,Action={actionid=203},}",
  [653935] = "{id=653935,Text='平心静气，摒弃所有的杂念。',Speaker=811915,ModelFace=1,ModelAct=8,}",
  [653936] = "{id=653936,Text='将意志注入誓言之书，获得它的承认。',Speaker=816564,ModelFace=1,ModelAct=867,}",
  [653937] = "{id=653937,Text='好啦喵，你已经踏出成为唤灵者的第一步喵。',Speaker=816564,ModelFace=1,ModelAct=867,}",
  [653938] = "{id=653938,Text='切记多兰族的力量可不是用来滥用的喵。',Speaker=816564,ModelFace=1,ModelAct=867,}",
  [653939] = "{id=653939,Text='咕咕咕咕，原来你适合这个职业啊。拥有「命运的加护」的你，一定可以成为了不起的胧的！',Speaker=811915,ModelFace=1,ModelAct=8,}",
  [653940] = "{id=653940,Text='不过凡事还得一步一步来。想成为胧，首先要转职成忍者。',Speaker=811915,ModelFace=1,ModelAct=8,Action={actionid=202},}",
  [653941] = "{id=653941,Text='你去寻找胧的导师：无痕行者胧月夜吧！他会帮你转职为忍者的。',Speaker=811915,ModelFace=1,ModelAct=8,}",
  [653948] = "{id=653948,Text='[c][ffff00][PlayerName][-][/c]，又见面了。选择职业的过程都顺利吗？',Speaker=811888,Option='{很顺利,2},{有点小情况,3}',ModelFace=1,ModelAct=867,Emoji=17,}",
  [653949] = "{id=653949,Text='唔，奥尔加竟然做了这样的事吗？',Speaker=811888,ModelFace=1,ModelAct=867,}",
  [653950] = "{id=653950,Text='一会儿我会好好教育它的。',Speaker=811888,ModelFace=1,ModelAct=867,Emoji=12,}",
  [653951] = "{id=653951,Text='嗯，我就知道你没问题的。',Speaker=811888,ModelFace=1,ModelAct=867,Emoji=20,}",
  [653952] = "{id=653952,Text='目前为止，你已经完成了所有的初学者任务，可在在学院中自由活动、暂时放松一下。',Speaker=811888,ModelFace=1,ModelAct=867,Emoji=27,}",
  [653953] = "{id=653953,Text='王立克里图拉学院是一个崇尚自由、包罗万象的地方，你一定能发现很多有趣的细节。',Speaker=811888,ModelFace=1,ModelAct=867,}",
  [653954] = "{id=653954,Text='另外，遇到有人求助时，也请不要拒绝。',Speaker=811888,ModelFace=4,ModelAct=868,Action={actionid=868},}",
  [653955] = "{id=653955,Text='帮助他人是学院的传统，也是许多传奇冒险的开始。',Speaker=811888,ModelFace=1,ModelAct=867,}",
  [653956] = "{id=653956,Text='被命运选中的勇者，去寻找自己的机缘吧~',Speaker=811888,ModelFace=1,ModelAct=867,}",
  [653957] = "{id=653957,Text='别扒拉我，我要用眼泪在地上写7个大大的“惨”字。',Speaker=811917,Option='你怎么了？',Emoji=24,}",
  [653958] = "{id=653958,Text='你看不出来吗？我在经受爱情的折磨啊！',Speaker=811917,}",
  [653959] = "{id=653959,Text='我的发小兼恋人又生气了，却连原因都不想告诉我。',Speaker=811917,Emoji=24,}",
  [653960] = "{id=653960,Text='她一定是厌倦我了，毕竟她是那么优秀，而我只是个学院吊尾车。',Speaker=811917,Emoji=42,}",
  [653961] = "{id=653961,Text='我们的感情走到了尽头，我的人生已经没有希望了！',Speaker=811917,Option='别那么悲观啊',Emoji=42,}",
  [653962] = "{id=653962,Text='说、说得也对！咸鱼还要翻身呢，被甩之前，我总得挣扎一下。',Speaker=811917,ModelFace=1,ModelAct=0,}",
  [653963] = "{id=653963,Text='这位学弟你能代我打探一下她生气的原因吗？',Speaker=811917,ModelFace=1,ModelAct=0,}",
  [653964] = "{id=653964,Text='这位学妹你能代我打探一下她生气的原因吗？',Speaker=811917,ModelFace=1,ModelAct=0,}",
  [653965] = "{id=653965,Text='辛妮娅很喜欢新生，应该会向你透露一些线索。',Speaker=811917,Option='{好的,9},{我还有事,8}',ModelFace=1,ModelAct=0,}",
  [653966] = "{id=653966,Text='呃……那我在这里等你一会儿？帮人帮到底嘛，拜托你了！',Speaker=811917,ModelFace=1,ModelAct=0,}",
  [653967] = "{id=653967,Text='太感谢了！辛妮娅就在喷泉附近，请你和她聊一聊吧！',Speaker=811917,ModelFace=1,ModelAct=0,}",
  [653968] = "{id=653968,Text='混蛋雷纳德，气死我了，气死我了！',Speaker=811918,Option='学姐你好呀？',ModelFace=1,ModelAct=867,Emoji=12,}",
  [653969] = "{id=653969,Text='嗯？是小学弟呀！',Speaker=811918,ModelFace=1,ModelAct=867,}",
  [653970] = "{id=653970,Text='不好意思，让你看到我失态了。',Speaker=811918,ModelFace=1,ModelAct=867,}",
  [653971] = "{id=653971,Text='你需要什么帮助吗？',Speaker=811918,Option='解释',ModelFace=1,ModelAct=867,Emoji=38,}",
  [653972] = "{id=653972,Text='原来是担心我啊？真是个可爱的小家伙！',Speaker=811918,ModelFace=1,ModelAct=867,Action={actionid=32},}",
  [653973] = "{id=653973,Text='其实也不是什么严重的事情啦……',Speaker=811918,ModelFace=1,ModelAct=867,Emoji=12,}",
  [653974] = "{id=653974,Text='就是有个混蛋，明明答应过我会好好学习，却连书都没有开过，就把书还回了藏书馆去。',Speaker=811918,ModelFace=1,ModelAct=867,}",
  [653975] = "{id=653975,Text='而且、而且……',Speaker=811918,ModelFace=1,ModelAct=867,}",
  [653976] = "{id=653976,Text='那本书里还有我难得写的情书啦！承载了我的鼓励和心意！',Speaker=811918,ModelFace=1,ModelAct=867,Emoji=12,}",
  [653977] = "{id=653977,Text='然而雷纳德那个白痴根本没有收到！',Speaker=811918,ModelFace=1,ModelAct=867,Action={actionid=206},}",
  [653978] = "{id=653978,Text='真是气死我啦！啊啊啊——！！！',Speaker=811918,ModelFace=1,ModelAct=867,Action={actionid=206},}",
  [653979] = "{id=653979,Text='真相居然是这样吗？那本书里还夹着辛妮娅的情书！',Speaker=811917,ModelFace=1,ModelAct=0,Emoji=1,}",
  [653980] = "{id=653980,Text='是我的错，不仅让她失望，还错失了她的心意。',Speaker=811917,ModelFace=1,ModelAct=0,Action={actionid=206},}",
  [653981] = "{id=653981,Text='不行，我得挽回这一切！',Speaker=811917,ModelFace=1,ModelAct=0,}",
  [653982] = "{id=653982,Text='辛妮娅的情书不能留在藏书馆里。如果让别人看到这封情书还宣扬出去，一定会令她为难的。',Speaker=811917,ModelFace=1,ModelAct=0,}",
  [653983] = "{id=653983,Text='[c][ffff00][PlayerName][-][/c]，请和我一起找回辛妮娅的情书吧！',Speaker=811917,Option='好',ModelFace=7,ModelAct=869,Action={actionid=869},}",
  [653984] = "{id=653984,Text='谢谢你，[c][ffff00][PlayerName][-][/c]，今天你就是我异父异母的亲兄弟了！',Speaker=811917,ModelFace=1,ModelAct=0,}",
  [653985] = "{id=653985,Text='谢谢你，[c][ffff00][PlayerName][-][/c]，今天你就是我异父异母的亲姐姐了！',Speaker=811917,ModelFace=1,ModelAct=0,}",
  [653986] = "{id=653986,Text='我们这就出发去皇家藏书馆吧！',Speaker=811917,ModelFace=1,ModelAct=0,}",
  [653987] = "{id=653987,Text='在我印象里，辛妮娅为我借的应该是一本历史书。',Speaker=811917,ModelFace=1,ModelAct=0,}",
  [653988] = "{id=653988,Text='我们分头搜寻吧，但愿它还没被人借走。',Speaker=811917,ModelFace=1,ModelAct=0,}",
  [653989] = "{id=653989,Text='“千年前，魔王梦罗克连同龙族一起向神族与巨人族发起战争，试图夺取九界的统治权。',Speaker=811922,}",
  [653990] = "{id=653990,Text='最后神族与巨人族险胜，迫使梦罗克逃往异世界。',Speaker=811922,}",
  [653991] = "{id=653991,Text='而为了拯救因战争而危在旦夕的天地树，始祖巨人伊米尔牺牲自己，用自己的血肉重铸了九界。',Speaker=811922,}",
  [653992] = "{id=653992,Text='之后重伤的神王奥丁也遭受魔狼芬里尔的偷袭，至今下落不明……',Speaker=811922,}",
  [653993] = "{id=653993,Text='从此，诸神时代落幕，人类登上历史的舞台。”',Speaker=811922,}",
  [653994] = "{id=653994,Text='没有找到辛妮娅的情书。',}",
  [653995] = "{id=653995,Text='“相传，王立克里图拉学院的改建有神族参与。为弥补诸神黄昏中折损的英灵，一位女武神受命下凡，引领具有潜质的冒险者们。',Speaker=811923,}",
  [653996] = "{id=653996,Text='群星跟着她一起降落，形成了星泪森林的湖泊。而这位女武神至今仍潜伏在学院中，不断观察、培养着新生们……”',Speaker=811923,}",
  [653997] = "{id=653997,Text='没有找到辛妮娅的情书。',}",
  [653998] = "{id=653998,Text='“……勇士们挫败了巴风特复活魔王梦罗克的阴谋，保卫了米德加尔特大陆的和平。',Speaker=811924,}",
  [653999] = "{id=653999,Text='但是，一切都还没有结束……',Speaker=811924,}",
  [654000] = "{id=654000,Text='一个名为女神之手的组织在阴暗中伸出邪恶的双手，为掠夺散落在世界各地的伊米尔之心碎片，不择手段。',Speaker=811924,}",
  [654001] = "{id=654001,Text='有一件事情已经毋庸置疑：我们应当阻止女神之手，守护米德加尔特大陆的和平。”',Speaker=811924,}",
  [654002] = "{id=654002,Text='找到辛妮娅的情书啦！',}",
  [654003] = "{id=654003,Text='怎么样，找到辛妮娅的情书了吗？',Speaker=811917,ModelFace=1,ModelAct=0,}",
  [654004] = "{id=654004,Text='太好了，找回情书，辛妮娅应该能原谅我了。',Speaker=811917,ModelFace=1,ModelAct=0,}",
  [654005] = "{id=654005,Text='[c][ffff00][PlayerName][-][/c]，我们离开这里吧！',Speaker=811917,ModelFace=1,ModelAct=0,}",
  [654006] = "{id=654006,Text='[c][ffff00][PlayerName][-][/c]，我刚刚突然想到：',Speaker=811917,ModelFace=1,ModelAct=0,}",
  [654007] = "{id=654007,Text='就这么两手空空地跑去道歉，会不会显得很没诚意啊？',Speaker=811917,Option='{是有点,15},{不至于吧,16}',ModelFace=1,ModelAct=0,}",
  [654008] = "{id=654008,Text='果然，你也是这样认为的。',Speaker=811917,ModelFace=1,ModelAct=0,}",
  [654009] = "{id=654009,Text='可能吧……但不做些什么，总觉得心里过意不去。',Speaker=811917,ModelFace=1,ModelAct=0,}",
  [654010] = "{id=654010,Text='这样吧，辛妮娅很喜欢星泪湖畔的月光花，我们一起采集月光花，送给她做赔礼怎么样？',Speaker=811917,Option='{没问题,18},{这是你的事,19}',ModelFace=1,ModelAct=0,}",
  [654011] = "{id=654011,Text='呜哇！你真是一个绝世大好人，我和辛妮娅修成正果的时候，绝对会请你来参加婚礼的！',Speaker=811917,ModelFace=3,ModelAct=0,Action={actionid=39},}",
  [654012] = "{id=654012,Text='诶，别、别这么绝情嘛！我们可是刚刚相认过的亲兄弟啊！那地方我一个人不敢去啊！',Speaker=811917,ModelFace=1,ModelAct=0,Emoji=1,}",
  [654013] = "{id=654013,Text='诶，别、别这么绝情嘛！我们可是刚刚相认过的姐弟啊！那地方我一个人不敢去啊！',Speaker=811917,ModelFace=1,ModelAct=0,Emoji=1,}",
  [654014] = "{id=654014,Text='算我求你啦，不会花费很多时间的，事后我请你在紫藤树餐厅吃饭呀~',Speaker=811917,Option='好吧……',ModelFace=8,ModelAct=869,Action={actionid=869},}",
  [654015] = "{id=654015,Text='万分感谢，那我们现在就去星泪湖畔吧！',Speaker=811917,ModelFace=1,ModelAct=0,}",
  [654016] = "{id=654016,Text='过了这座桥，就是星泪湖北岸，月光花就生长在那边的林地里。',Speaker=811917,ModelFace=1,ModelAct=0,}",
  [654017] = "{id=654017,Text='不过，采集鲜花的时候，请不要离我太远……',Speaker=811917,ModelFace=1,ModelAct=0,Emoji=37,}",
  [654018] = "{id=654018,Text='如果我喊救命，一定要赶来救我啊！',Speaker=811917,Option='啥？',ModelFace=2,ModelAct=868,Action={actionid=868},}",
  [654019] = "{id=654019,Text='你没听说过学院的恐怖故事吗？',Speaker=811917,ModelFace=1,ModelAct=0,}",
  [654020] = "{id=654020,Text='就是、就是学院里有个可怕的魔兽，专门惩罚不好好学习、到野外摸鱼的学生。',Speaker=811917,ModelFace=1,ModelAct=0,Emoji=18,}",
  [654021] = "{id=654021,Text='我的一个哥们儿，因为拖欠论文三周，被它叼着衣领挂到了树上。',Speaker=811917,ModelFace=1,ModelAct=0,Action={actionid=868},}",
  [654022] = "{id=654022,Text='我的另一个哥们儿，因为三次补考不及格，被它用尾巴扫进了星泪湖。',Speaker=811917,ModelFace=1,ModelAct=867,Action={actionid=868},}",
  [654023] = "{id=654023,Text='我有预感，它还会找上我的……因为和辛妮娅闹矛盾，我都两天没去上课了。',Speaker=811917,Option='那我们回去？',ModelFace=2,ModelAct=868,Emoji=37,Action={actionid=868},}",
  [654024] = "{id=654024,Text='不、不行！为了挽回辛妮娅，我不能就这么放弃！',Speaker=811917,ModelFace=1,ModelAct=867,}",
  [654025] = "{id=654025,Text='我豁出去啦——！！！',Speaker=811917,ModelFace=1,ModelAct=867,}",
  [654026] = "{id=654026,Text='啊啊啊啊啊——！！！魔兽真的出现啦！！！',Speaker=811917,ModelFace=2,ModelAct=867,Action={actionid=867},}",
  [654027] = "{id=654027,Text='[c][ffff00][PlayerName][-][/c]，救命啊！！！！！',Speaker=811917,ModelFace=1,ModelAct=867,}",
  [654028] = "{id=654028,Text='[c][ffff00][PlayerName][-][/c]，快醒醒，你可不能沉睡在黑夜里。',Speaker=811920,}",
  [654029] = "{id=654029,Text='这是哪里？我为什么在这儿？',}",
  [654030] = "{id=654030,Text='你不记得了吗？你遇到克鲁鲁的袭击，失去了「命运的加护」。',Speaker=811920,Emoji=8,}",
  [654031] = "{id=654031,Text='重伤令你陷入昏迷，如今你正徘徊在梦境的世界里。',Speaker=811920,Option='{是我太莽撞了,2},{是我太弱小了,3}',}",
  [654032] = "{id=654032,Text='是我太莽撞了。贸然与克鲁鲁战斗，没有守护好「命运的加护」。',}",
  [654033] = "{id=654033,Text='是我太弱小了。想要帮助大家，却丢失了「命运的加护」。',}",
  [654034] = "{id=654034,Text='别灰心呀。挫折并不意味着失败，而是一次成长的机会。',Speaker=811920,}",
  [654035] = "{id=654035,Text='我会指引你突破心灵的桎梏，找寻到新的力量的。',Speaker=811920,}",
  [654036] = "{id=654036,Text='……你究竟是？',}",
  [654037] = "{id=654037,Text='呵呵，你就当我是你的守护者好啦。',Speaker=811920,}",
  [654038] = "{id=654038,Text='请朝前迈进，找回你的勇气、信念和决心吧。',Speaker=811920,}",
  [654039] = "{id=654039,Text='另外，你也需要小心。你在现实中遇到的敌人，会投影成梦境中的梦魇。',Speaker=811920,}",
  [654040] = "{id=654040,Text='只有面对它、克服它，才能回到现实。',Speaker=811920,Option='明白了',}",
  [654041] = "{id=654041,Text='时间不多了，我们赶紧出发吧~',Speaker=811920,}",
  [654042] = "{id=654042,Text='重拾我，勇敢地迎接命运。',Speaker=811928,}",
  [654043] = "{id=654043,Text='重拾我，无悔地迎接命运。',Speaker=811929,}",
  [654044] = "{id=654044,Text='勇气和信念都找回来了。',Speaker=811920,}",
  [654045] = "{id=654045,Text='我们快前往下一重梦境吧！',Speaker=811920,}",
  [654046] = "{id=654046,Text='[c][ffff00][PlayerName][-][/c]，你看。梦境的出口就在那里。',Speaker=811920,}",
  [654047] = "{id=654047,Text='勇气、信念和决心都找齐了，我们快从梦境出口返回现实吧~',Speaker=811920,}",
  [654048] = "{id=654048,Text='放弃吧，愚蠢的两脚兽。你连我都战胜不了，还妄想成为拯救世界的勇士？',Speaker=811921,}",
  [654049] = "{id=654049,Text='失去命运的加护，你只是个再平庸不过的凡人。',Speaker=811921,}",
  [654050] = "{id=654050,Text='[c][ffff00][PlayerName][-][/c]，别被梦魇动摇。',Speaker=811920,}",
  [654051] = "{id=654051,Text='真正的力量源自内心，而非外人所赋予。',Speaker=811920,}",
  [654052] = "{id=654052,Text='只要你愿意为这个世界付出，你就是真正的勇士！',Speaker=811920,}",
  [654053] = "{id=654053,Text='用你的心灵之力战胜它！',Speaker=811920,}",
  [654054] = "{id=654054,Text='我还有勇气、信念和决心！',}",
  [654055] = "{id=654055,Text='我会打败你的！',}",
  [654056] = "{id=654056,Text='克鲁鲁消失了。',}",
  [654057] = "{id=654057,Text='它果然只是一个幻象。',}",
  [654058] = "{id=654058,Text='[c][ffff00][PlayerName][-][/c]，你做的很好。我就知道你能够超越自我的！',Speaker=811920,}",
  [654059] = "{id=654059,Text='走吧，快回去吧，大家都在梦境外等着你呢。',Speaker=811920,}",
  [654073] = "{id=654073,Text='呜哇——是我跑得太慢了，没能赶回来支援你。[c][ffff00][PlayerName][-][/c]，你好惨啊~~~',Speaker=811917,ModelFace=1,ModelAct=867,}",
  [654074] = "{id=654074,Text='……喂喂，[c][ffff00][PlayerName][-][/c]只是昏过去，又不是死掉了！',Speaker=811934,}",
  [654075] = "{id=654075,Text='你稍微克制一下啊。',Speaker=811934,}",
  [654076] = "{id=654076,Text='你们看，冒险者这不就醒来了吗~',Speaker=811889,}",
  [654077] = "{id=654077,Text='我们找到你的时候，你一动不动地躺在地上，吓坏大家咯喵。',Speaker=811889,ModelFace=1,ModelAct=867,}",
  [654078] = "{id=654078,Text='不过还好，经过我的治疗，你总算清醒了。',Speaker=811889,Option='克鲁鲁的下落',ModelFace=1,ModelAct=867,}",
  [654079] = "{id=654079,Text='咪呜，这、这个有在处理啦！',Speaker=811889,ModelFace=1,ModelAct=867,}",
  [654080] = "{id=654080,Text='希格德莉法已经带领加拉尔护卫队前去讨伐克鲁鲁啦，只不过……',Speaker=811889,Option='只不过？',ModelFace=1,ModelAct=867,}",
  [654081] = "{id=654081,Text='只不过讨伐不怎么顺利。',Speaker=811934,ModelFace=1,ModelAct=867,}",
  [654082] = "{id=654082,Text='在你昏迷期间，我们收到一条简短的求援信息，随后就和先遣队彻底失联。',Speaker=811934,ModelFace=1,ModelAct=867,}",
  [654083] = "{id=654083,Text='恐怕「命运的加护」壮大了克鲁鲁的力量，令希格德莉法他们陷入困境。',Speaker=811934,Option='{我也来帮忙,0},{我也要战斗,0}',ModelFace=1,ModelAct=867,}",
  [654084] = "{id=654084,Text='太危险了！你被夺走「命运的加护」，成了普通人。对上暴走的克鲁鲁很可能失败甚至死掉。',Speaker=811917,ModelFace=1,ModelAct=867,}",
  [654085] = "{id=654085,Text='[c][ffff00][PlayerName][-][/c]。你可得想清楚啊！',Speaker=811917,ModelFace=1,ModelAct=0,}",
  [654086] = "{id=654086,Text='我有勇气、信念和决心！',}",
  [654087] = "{id=654087,Text='我愿和大家并肩作战，解决学院的危机！',}",
  [654088] = "{id=654088,Text='勇气、信念和决心嘛……我能感受到，力量正重新在你的身体里复苏。',Speaker=811889,ModelFace=1,ModelAct=867,}",
  [654089] = "{id=654089,Text='不是命运女神赋予的加护，而是源自你心灵的那部分。',Speaker=811889,ModelFace=1,ModelAct=867,}",
  [654090] = "{id=654090,Text='相比过去，它变得更加纯粹、更加强大。',Speaker=811889,ModelFace=1,ModelAct=867,}",
  [654091] = "{id=654091,Text='既然如此，那你确实具备参与战斗的资格。',Speaker=811934,ModelFace=1,ModelAct=867,}",
  [654092] = "{id=654092,Text='只是在出发前，还有些事情需要确认。',Speaker=811934,ModelFace=1,ModelAct=867,}",
  [654093] = "{id=654093,Text='雷纳德，你先回学院去。',Speaker=811934,ModelFace=1,ModelAct=867,}",
  [654094] = "{id=654094,Text='[c][ffff00][PlayerName][-][/c]，我们换个地方细说。',Speaker=811934,ModelFace=1,ModelAct=867,}",
  [654095] = "{id=654095,Text='这个传送阵会将你传送到星泪森林的深处，也就是克鲁鲁的老巢。',Speaker=811934,ModelFace=1,ModelAct=867,}",
  [654096] = "{id=654096,Text='你不仅需要击败各种各样的魔物，还需要应对森林的复杂环境。',Speaker=811934,ModelFace=1,ModelAct=867,}",
  [654097] = "{id=654097,Text='这将会是一场艰难的战斗。',Speaker=811889,ModelFace=1,ModelAct=867,}",
  [654098] = "{id=654098,Text='你准备好挑战克鲁鲁、夺回「命运的加护」了吗？',Speaker=811889,Option='{准备好了！,5},{再等等,3}',ModelFace=1,ModelAct=867,}",
  [654099] = "{id=654099,Text='没问题的喵。我理解你需要时间做些心理建设！',Speaker=811889,ModelFace=1,ModelAct=867,}",
  [654100] = "{id=654100,Text='那么，请站到传送阵上去。我会用魔法把你传送到密林深处去。',Speaker=811889,ModelFace=1,ModelAct=867,}",
  [654101] = "{id=654101,Text='我们很欣赏你挺身而出的勇气。也正因为如此，我们想在战前为你提供助力。',Speaker=811934,ModelFace=1,ModelAct=867,}",
  [654102] = "{id=654102,Text='在王立克里图拉学院内部，留存着一个古老的仪式：',Speaker=811889,ModelFace=1,ModelAct=867,}",
  [654103] = "{id=654103,Text='拥有坚定心灵的勇士，可以在「传承之间」接受历代英灵的传承，快速提升冒险经验和职业技能。',Speaker=811889,ModelFace=1,ModelAct=869,}",
  [654104] = "{id=654104,Text='但这个仪式对于人体负荷很大，恐怕一生只有一次机会。',Speaker=811889,ModelFace=1,ModelAct=867,}",
  [654105] = "{id=654105,Text='你确定要在这时候使用吗？',Speaker=811889,ModelFace=1,ModelAct=867,}",
  [654106] = "{id=654106,Text='[c][ffff00]【你已经获得一次快速三转机会。选择“使用”，可使当前角色快速升级到base120、三转job60；选择“不用”，将保留快速三转机会。每个账号仅有一次快速三转资格。】[-][/c]',Speaker=811889,Option='{[c][ffff00]使用[-][/c],61},{不用,51}',ModelFace=1,ModelAct=867,}",
  [654107] = "{id=654107,Text='[c][ffff00]确定要把机会留到以后吗？[-][/c]',Speaker=811889,Option='{确定,53},{再考虑一下,52}',ModelFace=1,ModelAct=867,}",
  [654108] = "{id=654108,Text='行，我将保留你进入「传承之间」的机会。',Speaker=811889,Option='{好的！,54},{我改变主意了,52}',ModelFace=1,ModelAct=867,}",
  [654109] = "{id=654109,Text='我相信，你可以用自己心灵的力量打败魔兽的！',Speaker=811889,ModelFace=1,ModelAct=867,}",
  [654110] = "{id=654110,Text='你已经做好觉悟，决定挑战克鲁鲁、夺回「命运的加护」了吗？',Speaker=811889,Option='{准备好了！,57},{再等等,56}',ModelFace=1,ModelAct=867,}",
  [654111] = "{id=654111,Text='没问题的喵。我理解你需要时间做些心理建设！',Speaker=811889,ModelFace=1,ModelAct=867,}",
  [654112] = "{id=654112,Text='那么，请站到传送阵上去。我会用魔法把你传送到密林深处去。',Speaker=811889,ModelFace=1,ModelAct=867,}",
  [654113] = "{id=654113,Text='[c][ffff00]不会后悔这个选择吗？[-][/c]',Speaker=811889,Option='{不后悔,63},{再考虑一下,62}',ModelFace=1,ModelAct=867,}",
  [654114] = "{id=654114,Text='[c][ffff00]确定吗？绝不反悔吗？[-][/c]',Speaker=811889,Option='{确定,64},{我改变主意了,62}',ModelFace=1,ModelAct=867,}",
  [654115] = "{id=654115,Text='好的，那我现在就用魔法将你传送回初心殿堂。',Speaker=811889,ModelFace=1,ModelAct=867,}",
  [654116] = "{id=654116,Text='找到你的职业导师，他会带你去接受传承的。',Speaker=811889,ModelFace=1,ModelAct=867,}",
  [654117] = "{id=654117,Text='我已经知晓你前来的目的，但你是否抉择好了自己的道路。',Speaker=816546,ModelFace=1,ModelAct=867,}",
  [654118] = "{id=654118,Text='一旦接受了符文骑士的传承，你就不能再成为皇家卫士了。',Speaker=816546,ModelFace=1,ModelAct=867,}",
  [654119] = "{id=654119,Text='你确定要这么做吗？',Speaker=816546,Option='{确定,20},{拒绝,30}',ModelFace=1,ModelAct=867,}",
  [654120] = "{id=654120,Text='好，那我现在就带你去「传承之间」。',Speaker=816546,ModelFace=1,ModelAct=867,}",
  [654121] = "{id=654121,Text='好，那你可以找法拉昂接受皇家卫士的传承。',Speaker=816546,ModelFace=1,ModelAct=867,}",
  [654122] = "{id=654122,Text='我已经知晓你前来的目的，但你是否抉择好了自己的道路。',Speaker=816544,ModelFace=1,ModelAct=867,}",
  [654123] = "{id=654123,Text='一旦接受了皇家卫士的传承，你就不能再成为符文骑士了。',Speaker=816544,ModelFace=1,ModelAct=867,}",
  [654124] = "{id=654124,Text='你确定要这么做吗？',Speaker=816544,Option='{确定,20},{拒绝,30}',ModelFace=1,ModelAct=867,}",
