  [654202] = "{id=654202,Text='我已经知晓你前来的目的，但你是否抉择好了自己的道路。',Speaker=816567,ModelFace=1,ModelAct=763,}",
  [654203] = "{id=654203,Text='一旦接受了胧的传承，你就不能再成为进阶初心者了。',Speaker=816567,ModelFace=1,ModelAct=763,}",
  [654204] = "{id=654204,Text='你确定要接受胧的传承吗？',Speaker=816567,Option='{确定,20},{拒绝,30}',ModelFace=1,ModelAct=763,}",
  [654205] = "{id=654205,Text='好，那我现在就带你去「传承之间」。',Speaker=816567,ModelFace=1,ModelAct=763,}",
  [654206] = "{id=654206,Text='好，那你再考虑考虑。',Speaker=816567,ModelFace=1,ModelAct=763,}",
  [654207] = "{id=654207,Text='一口气传承到太多力量，你是不是感到有些混乱呢？',Speaker=816567,ModelFace=1,ModelAct=763,}",
  [654208] = "{id=654208,Text='我现在就帮你梳理力量、[c][ffff00]添加技能点[-][/c]。',Speaker=816567,ModelFace=1,ModelAct=763,}",
  [654209] = "{id=654209,Text='忍者一共有三种流派：刀忍擅长近战物理攻击，依靠连击与暴击造成高爆发伤害。',Speaker=816567,ModelFace=1,ModelAct=763,}",
  [654210] = "{id=654210,Text='镖忍擅长远程物理伤害，使用风魔手里剑作为武器，持续伤害能力较强。',Speaker=816567,ModelFace=1,ModelAct=763,}",
  [654211] = "{id=654211,Text='法忍精通忍术与通灵术，是攻击方式更为多样的法术输出者。',Speaker=816567,ModelFace=1,ModelAct=763,}",
  [654212] = "{id=654212,Text='你要选择哪一种流派加点呢？',Speaker=816567,Option='{刀忍,10},{镖忍,20},{法忍,30}',ModelFace=1,ModelAct=763,}",
  [654213] = "{id=654213,Text='好的，我现在就帮你完成加点。',Speaker=816567,ModelFace=1,ModelAct=763,}",
  [654214] = "{id=654214,Text='接下来你会面临一场艰难又危险的战斗。',Speaker=816567,ModelFace=1,ModelAct=763,}",
  [654215] = "{id=654215,Text='因为这是你初次应对强敌，我们想为你提供战斗提示。你是否需要呢？',Speaker=816567,ModelFace=1,ModelAct=763,}",
  [654216] = "{id=654216,Text='[c][ffff00]【选择“需要”将开启3转职业教学辅助战斗，推荐新人采用。】[-][/c]',Speaker=816567,Option='{需要,8},{不需要,9}',ModelFace=1,ModelAct=763,}",
  [654217] = "{id=654217,Text='我知道了。',Speaker=816567,ModelFace=1,ModelAct=763,}",
  [654218] = "{id=654218,Text='这些装备和道具你收下，务必在战斗中好好利用他们。',Speaker=816567,ModelFace=1,ModelAct=763,}",
  [654219] = "{id=654219,Text='做好准备的话，就告知我一声，我会将你传送到恶魔的老巢去。',Speaker=816567,ModelFace=1,ModelAct=763,}",
  [654220] = "{id=654220,Text='[c][ffff00]【选择“需要”将开启3转职业教学辅助战斗，推荐新人采用。】[-][/c]',Speaker=816567,Option='{需要,11},{不需要,15}',ModelFace=1,ModelAct=763,}",
  [654221] = "{id=654221,Text='[c][ffff00]【选择“需要”将开启3转职业教学辅助战斗，推荐新人采用。】[-][/c]',Speaker=816567,Option='{需要,21},{不需要,25}',ModelFace=1,ModelAct=763,}",
  [654222] = "{id=654222,Text='[c][ffff00]【选择“需要”将开启3转职业教学辅助战斗，推荐新人采用。】[-][/c]',Speaker=816567,Option='{需要,31},{不需要,35}',ModelFace=1,ModelAct=763,}",
  [654223] = "{id=654223,Text='既然你准备好了，那就出发吧！',Speaker=816567,Option='{好的,14},{稍等一下,12}',ModelFace=1,ModelAct=763,}",
  [654224] = "{id=654224,Text='既然你准备好了，那就出发吧！',Speaker=816567,Option='{好的,18},{稍等一下,16}',ModelFace=1,ModelAct=763,}",
  [654225] = "{id=654225,Text='既然你准备好了，那就出发吧！',Speaker=816567,Option='{好的,24},{稍等一下,22}',ModelFace=1,ModelAct=763,}",
  [654226] = "{id=654226,Text='既然你准备好了，那就出发吧！',Speaker=816567,Option='{好的,28},{稍等一下,26}',ModelFace=1,ModelAct=763,}",
  [654227] = "{id=654227,Text='既然你准备好了，那就出发吧！',Speaker=816567,Option='{好的,34},{稍等一下,32}',ModelFace=1,ModelAct=763,}",
  [654228] = "{id=654228,Text='既然你准备好了，那就出发吧！',Speaker=816567,Option='{好的,38},{稍等一下,36}',ModelFace=1,ModelAct=763,}",
  [654230] = "{id=654230,Text='我在这里哦，命运之风！',Speaker=811920,}",
  [654231] = "{id=654231,Text='莉法，你是女武神！？',}",
  [654232] = "{id=654232,Text='是的，[c][ffff00][PlayerName][-][/c]。我是女武神，也是你在学院的接引人。',Speaker=811936,}",
  [654233] = "{id=654233,Text='神谕曾揭示：“尤克特拉西尔之巅被阴云笼罩，唯有如风之人才能驱散危机。”',Speaker=811936,Action={actionid=9},}",
  [654234] = "{id=654234,Text='为了让被选中的人——也就是你，强大到足以承载命运的重托。我们特意安排了你在学院的这段旅程。',Speaker=811936,Option='原来如此',}",
  [654235] = "{id=654235,Text='嗯嗯。现在的你已经是个合格的勇士了，也该从学院毕业、开启新的冒险。',Speaker=811936,}",
  [654236] = "{id=654236,Text='但在这之前，先从我手里接受“命运的赠礼”吧。它们能在之后的冒险中为你提供助力。',Speaker=811936,}",
  [654237] = "{id=654237,Text='而你，也没有辜负大家的期望。',Speaker=811936,}",
  [654238] = "{id=654238,Text='能战胜了克鲁鲁，正是你的心灵之力凌驾于命运之力的证明。',Speaker=811936,}",
  [654239] = "{id=654239,Text='[c][ffff00][PlayerName][-][/c]，你已经成长为真正的勇士，足以肩负守护世界的重任。',Speaker=811936,}",
  [654240] = "{id=654240,Text='唉，这一次是真的没东西送你啦~我们只能说再见咯……',Speaker=811954,Option='再见，莉法！',}",
  [654241] = "{id=654241,Text='？？？：不，还不到时候！请等一等！',Speaker=811935,}",
  [654242] = "{id=654242,Text='哇，拍得好棒呢！',Speaker=811943,}",
  [654243] = "{id=654243,Text='谢谢你，我们会把这张照片，来带着你的心意一起珍藏的。',Speaker=811943,Option='再见了，大家！',}",
  [654244] = "{id=654244,Text='现在也到说再见的时候了，和大家告别吧！',Speaker=811943,}",
  [654245] = "{id=654245,Text='别忘了我咕~',Speaker=811914,}",
  [654246] = "{id=654246,Text='珍重啊，挚友！',Speaker=811917,}",
  [654247] = "{id=654247,Text='加油前进吧！',Speaker=811934,}",
  [654248] = "{id=654248,Text='要保重哦喵~',Speaker=811889,}",
  [654249] = "{id=654249,Text='再见啦！',Speaker=811887,}",
  [654250] = "{id=654250,Text='终于轮到你和我告别啦。',Speaker=811951,}",
  [654251] = "{id=654251,Text='在你离开学院之前，我还有些东西要交待你：',Speaker=811951,Action={actionid=88},}",
  [654252] = "{id=654252,Text='诶嘿！第一，我要交给你「技能重置棒」。',Speaker=811954,}",
  [654253] = "{id=654253,Text='技能加点失误时，可以使用它。',Speaker=811954,}",
  [654254] = "{id=654254,Text='第二，请你收好这颗「轮回之石」。',Speaker=811954,}",
  [654255] = "{id=654255,Text='它能把所有分配过的素质点归零，方便你重新分配。',Speaker=811954,}",
  [654256] = "{id=654256,Text='第三，你还有一份神秘大礼要签收。',Speaker=811954,Emoji=17,Action={actionid=39},}",
  [654257] = "{id=654257,Text='——我要把自己送给你！',Speaker=811954,Option='{欸？！！！,0},{还有这种好事？,0}',}",
  [654258] = "{id=654258,Text='哈哈哈哈，当然是不可能的啦。',Speaker=811954,Emoji=17,}",
  [654259] = "{id=654259,Text='虽然我非常舍不得你，但我还有守护学院的职责在身。',Speaker=811954,}",
  [654260] = "{id=654260,Text='真正能送给你的，只有女武神的祝福而已。',Speaker=811954,Emoji=27,Action={actionid=32},}",
  [654261] = "{id=654261,Text='尤克特拉西尔的另一边危机四伏，期待着如风之人吹散阴云。”',Speaker=811951,}",
  [654262] = "{id=654262,Text='暂时再见了，[c][ffff00][PlayerName][-][/c]。',Speaker=811951,}",
  [654263] = "{id=654263,Text='总有一天，我会从他人口中再听到你的名字。那时，必将是世人把你的事迹传唱。',Speaker=811951,Option='再见，莉法！',}",
  [654264] = "{id=654264,Text='想启程前往普隆德拉时，告诉我一声就好。',Speaker=811951,Action={actionid=868},}",
  [654265] = "{id=654265,Text='我会指引你如何前往普隆德拉。',Speaker=811951,}",
  [654266] = "{id=654266,Text='你已经准备好前往普隆德拉了吗？',Speaker=811951,Option='{是的,4},{还没有,3}',}",
  [654267] = "{id=654267,Text='那么，去找[c][ffff00]卡普拉服务人员[-][/c]吧，她会送你去前往普隆德拉的~一路顺风哟！',Speaker=811951,}",
  [654268] = "{id=654268,Text='学院里还有什么事没有完成吗？',Speaker=811951,Emoji=8,}",
  [654269] = "{id=654269,Text='没关系，我会在这里等着你的。',Speaker=811951,}",
  [654274] = "{id=654274,Text='可以随意点击你想要移动到的位置哦~',Speaker=811937,ModelFace=1,ModelAct=867,}",
  [654275] = "{id=654275,Text='瞧瞧你这身穿的什么啊，真正勇士得像我这样金光闪闪！',Speaker=811892,Option='？？？',ModelFace=1,ModelAct=867,}",
  [654276] = "{id=654276,Text='我敢说你这身装备在野外活不过一个小时！',Speaker=811892,Option='我很强的',ModelFace=1,ModelAct=867,}",
  [654277] = "{id=654277,Text='哟，你别不信，看到那边的魔物了吗？',Speaker=811892,ModelFace=1,ModelAct=867,}",
  [654278] = "{id=654278,Text='稚嫩的年轻人!你要是能不全副武装的消灭他们，我就把我的装备送给你。',Speaker=811892,ModelFace=1,ModelAct=867,}",
  [654279] = "{id=654279,Text='这个明显打不过啊！',}",
  [654280] = "{id=654280,Text='使用装死吧！',}",
  [654281] = "{id=654281,Text='居然装死，我不打装死的人，走了！',Speaker=811921,}",
  [654282] = "{id=654282,Text='这次你可来不及装死了，哈哈哈哈，我要揍你一顿！',Speaker=811921,}",
  [654283] = "{id=654283,Text='哈哈哈哈，知道我的厉害了吧！',Speaker=811921,}",
  [654284] = "{id=654284,Text='什么鬼东西，快滚！',Speaker=811889,ModelFace=1,ModelAct=867,}",
  [654285] = "{id=654285,Text='这次算你好运，哼！',Speaker=811921,}",
  [654286] = "{id=654286,Text='都没血了，用紧急治疗啊，呆着干嘛！',Speaker=811889,ModelFace=1,ModelAct=867,}",
  [654287] = "{id=654287,Text='总算聪明点了，接下来去挂机打打搜集东西吧。',Speaker=811889,ModelFace=1,ModelAct=867,}",
  [654288] = "{id=654288,Text='搜集完东西以后用蝴蝶翅膀回去找希格德莉法。',Speaker=811889,ModelFace=1,ModelAct=867,}",
  [654289] = "{id=654289,Text='搜集完东西了，用蝴蝶翅膀回去找希格德莉法吧。',}",
  [654290] = "{id=654290,Text='好了，你现在是刀刃了，拿上你的武器，去把克鲁鲁教训了吧。',Speaker=816567,ModelFace=1,ModelAct=763,}",
  [654291] = "{id=654291,Text='对了，出发前你得去找一趟阿历克塞，他还欠你一套装备呢!',Speaker=816567,ModelFace=1,ModelAct=763,}",
  [654292] = "{id=654292,Text='我好歹是你的教官，你不会这么不给面子吧？',Speaker=811934,Option='你要赖账？',ModelFace=1,ModelAct=867,}",
  [654293] = "{id=654293,Text='这怎么能是赖账？我就不能……就不能……下次吗？这里这么多人……',Speaker=811934,Option='那我自己扒了',ModelFace=1,ModelAct=867,}",
  [654294] = "{id=654294,Text='没想到你还有点本事！',Speaker=811892,Option='把装备给我',ModelFace=1,ModelAct=867,}",
  [654295] = "{id=654295,Text='……你急什么，我现在就算脱下来给你，你也穿不了，你太孱弱了！',Speaker=811892,ModelFace=1,ModelAct=867,}",
  [654296] = "{id=654296,Text='根本承受不了我装备的力量，再去多练练吧。',Speaker=811892,ModelFace=1,ModelAct=867,}",
  [654298] = "{id=654298,Text='同车的小伙伴，你怎么还站在这里呀？',Speaker=811887,Action={actionid=32},}",
  [654299] = "{id=654299,Text='是不是被学院震撼到了？',Speaker=811887,Action={actionid=35},}",
  [654300] = "{id=654300,Text='其他人都和接引人报道过了，你也快去吧！',Speaker=811887,Action={actionid=31},}",
  [654301] = "{id=654301,Voice='Npc/Sigrdrifa_04',Text='欢迎来到王立克里图拉学院！我是你的接引人希格德莉法，你可以叫我莉法。',Speaker=811888,ModelFace=6,ModelAct=868,Emoji=17,BlackMask=1,}",
  [654302] = "{id=654302,Text='终于等到你了，[c][ffff00]命运之风[-][/c]~',Speaker=811888,Option='命运之风？',ModelFace=6,ModelAct=867,BlackMask=1,}",
  [654303] = "{id=654303,Text='哦？原来你不知道吗？你是被命运选中的冒险者呢！',Speaker=811888,ModelFace=1,ModelAct=868,BlackMask=1,}",
  [654304] = "{id=654304,Text='看——',Speaker=811888,}",
  [654305] = "{id=654305,Text='这三只金鸟是命运女神的使者。你会来到学院，正是因为它们的指引。',Speaker=811888,ModelFace=1,ModelAct=867,BlackMask=1,}",
  [654306] = "{id=654306,Text='在等你成长为合格的冒险者之后，它们就会带领你前往远方，履行特殊的使命。',Speaker=811888,ModelFace=1,ModelAct=868,BlackMask=1,}",
  [654307] = "{id=654307,Voice='Npc/Sigrdrifa_05',Text='嘻嘻，现在不明白也没关系，你会在未来的冒险中找到答案。',Speaker=811888,ModelFace=4,ModelAct=867,BlackMask=1,}",
  [654308] = "{id=654308,Text='现在，就先和我一起认识下学院吧。',Speaker=811888,ModelFace=4,ModelAct=868,BlackMask=1,}",
  [654309] = "{id=654309,Text='怎么样？对学院有所了解后，是不是很想马上开始你的学院生活？',Speaker=811888,Option='{是的！,0},{不行吗？,0}',ModelFace=1,ModelAct=867,BlackMask=1,}",
  [654310] = "{id=654310,Text='可以是可以，不过在那之前……',Speaker=811888,ModelFace=1,ModelAct=868,BlackMask=1,}",
  [654311] = "{id=654311,Text='你得先完成最高难度的入门课程——“全能初心者特训”！',Speaker=811888,Option='{诶，为什么？！,0},{太严格了吧？！,0}',ModelFace=1,ModelAct=867,BlackMask=1,}",
  [654312] = "{id=654312,Text='唔……因为你是[c][ffff00]命运之风[-][/c]啊！培养计划和普通学生的循序渐进不太一样。',Speaker=811888,ModelFace=3,ModelAct=868,BlackMask=1,}",
  [654313] = "{id=654313,Text='这个特训虽然辛苦，却能让你在最短时间内成长为出色的冒险者。',Speaker=811888,ModelFace=3,ModelAct=867,BlackMask=1,}",
  [654314] = "{id=654314,Text='你也想尽快走出学院，去广阔的世界展开冒险吧？',Speaker=811888,ModelFace=4,ModelAct=868,BlackMask=1,}",
  [654315] = "{id=654315,Text='那就拿上这把武器，去和教官阿历克塞打个招呼咯！',Speaker=811888,Option='{一听就很有意思,3},{好的,3},{不了吧,200}',ModelFace=1,ModelAct=867,BlackMask=1,}",
  [654316] = "{id=654316,Text='嗯嗯，阿历克塞就在星泪森林的新手训练场上等着你。',Speaker=811888,}",
  [654317] = "{id=654317,Text='哦对，你还不知道星泪森林在哪里~不过不用担心，我已经为你把阿历克塞的位置标注在地图上了~',Speaker=811888,}",
  [654318] = "{id=654318,Text='跟着我的标记走，就能找到他哦！',Speaker=811888,}",
  [654319] = "{id=654319,Text='欸，训练很有意思的，你真的不参加吗？！【选择不参加将[c][ffff00]无法体验完整的学院剧情[-][/c]。】',Speaker=811888,Option='{不参加,2},{[c][ffff00]那我参加[-][/c],3}',ModelFace=8,ModelAct=868,BlackMask=1,}",
  [654320] = "{id=654320,Text='唔，好吧。容我先查阅一下入学指南，看看你能不能跳过这个环节。',Speaker=811888,}",
  [654321] = "{id=654321,Voice='Npc/Aleksey_01',Text='哦豁！又来新人了。瞧你一脸的迷茫，肯定没什么冒险经验吧！',Speaker=811892,ModelFace=1,ModelAct=867,BlackMask=1,}",
  [654322] = "{id=654322,Text='先站到队伍里去，从最简单的体能训练开始吧！今天的内容是——挥剑一万次！',Speaker=811892,Option='全能初心者特训',ModelFace=6,ModelAct=868,BlackMask=1,}",
  [654323] = "{id=654323,Text='你误会了，我是来参加“全能初心者特训”的。',}",
  [654324] = "{id=654324,Voice='Npc/Aleksey_02',Text='哈哈哈哈~我没听错吧？“全能初心者特训”可不是给小菜鸟准备的。',Speaker=811892,Emoji=17,Action={actionid=868},}",
  [654325] = "{id=654325,Text='听着，小家伙。我理解青少年都有一段特殊的时期，觉得自己是天选之子，但这个项目真不是你能参加的。',Speaker=811892,Emoji=5,}",
  [654326] = "{id=654326,Text='我敢拿我这一身闪亮的英灵护甲打赌：你是绝对无法通过“特训”的！',Speaker=811892,Option='赌就赌',Action={actionid=868},}",
  [654327] = "{id=654327,Voice='Npc/Aleksey_03',Text='哦豁，你很有骨气！',Speaker=811892,Emoji=41,}",
  [654328] = "{id=654328,Text='既然如此，我就给你个机会。可别被魔物打得哭鼻子哦！',Speaker=811892,Emoji=17,Action={actionid=868},}",
  [654329] = "{id=654329,Text='特训可是很严酷的，你得在实战中快速掌握我传授的技巧，才能摆平所有魔物。',Speaker=811892,}",
  [654330] = "{id=654330,Text='做好准备的话，我们就开始吧！',Speaker=811892,Option='{开始吧,3},{再等等,2}',}",
  [654331] = "{id=654331,Text='全能初心者特训，现在开始。',Speaker=811934,}",
  [654332] = "{id=654332,Text='小菜鸟，看招~',Speaker=811934,}",
  [654333] = "{id=654333,Text='别愣着，拿起武器进行反击！',Speaker=811934,}",
  [654334] = "{id=654334,Text='哦豁，表现不错，但如果遇到更多魔物呢？',Speaker=811934,}",
  [654335] = "{id=654335,Text='扭扭~',Speaker=811940,}",
  [654336] = "{id=654336,Text='贴贴~',Speaker=811940,}",
  [654337] = "{id=654337,Text='不是吧！你还真搞定了？我的一世英名难道要终结于当众脱衣吗？！',Speaker=811934,Action={actionid=206},}",
  [654338] = "{id=654338,Text='哼哼，你也有这么狼狈的时候啊，阿历克塞。',Speaker=811921,}",
  [654339] = "{id=654339,Text='不如把这个新生交给我吧！他的身上有股神奇的力量，闻起来就和烤小鸟一样香~',Speaker=811921,}",
  [654340] = "{id=654340,Text='本大爷对他可是馋得很呐！',Speaker=811921,Emoji=28,}",
  [654341] = "{id=654341,Text='不好，克鲁鲁这混世魔王怎么来了！',Speaker=811934,}",
  [654342] = "{id=654342,Text='[c][ffff00][PlayerName][-][/c]，快后退。',Speaker=811934,}",
  [654343] = "{id=654343,Text='本大爷对她可是馋得很呐！',Speaker=811921,}",
  [654344] = "{id=654344,Text='看我的厉害！',Speaker=811921,}",
  [654345] = "{id=654345,Text='[c][ffff00][PlayerName][-][/c]，现在的你不是克鲁鲁的对手！先躺下装死保存实力吧！',Speaker=811934,}",
  [654346] = "{id=654346,Text='嘁——好弱的家伙，真无趣~',Speaker=811921,Emoji=8,}",
  [654347] = "{id=654347,Text='不过话说回来啊，你这小子究竟是什么人啊？竟然连克鲁鲁都惊动了。',Speaker=811892,}",
  [654348] = "{id=654348,Text='克鲁鲁！再不停手，我就叫女武，啊不，希格德莉法来揍你啦！',Speaker=811934,}",
  [654349] = "{id=654349,Text='什——么——！那老女人也会来！！',Speaker=811921,Emoji=1,}",
  [654350] = "{id=654350,Text='停手就停手，算你们走运，哼！',Speaker=811921,Emoji=12,Action={actionid=867},}",
  [654351] = "{id=654351,Text='呼……还好还好，虽然有点小意外，但这部分特训还是圆满结束了。',Speaker=811892,Emoji=25,Action={actionid=867},}",
  [654352] = "{id=654352,Text='不过话说回来啊，你这丫头究竟是什么人啊？竟然连克鲁鲁都惊动了。',Speaker=811892,Action={actionid=867},}",
  [654353] = "{id=654353,Text='等等，这、这好像是命运女神的使者啊！莫非你就是[c][ffff00]命运之风[-][/c]？',Speaker=811892,Option='{没错,0},{正是在下,0}',Emoji=1,Action={actionid=867},}",
  [654354] = "{id=654354,Text='你这家伙！干嘛瞒着我！早知道我就不打这个赌了。',Speaker=811892,Option='那你的装备？',Emoji=24,Action={actionid=206},}",
  [654355] = "{id=654355,Text='记着呢记着呢，真是个难缠的小鬼。',Speaker=811892,Action={actionid=867},}",
  [654356] = "{id=654356,Text='装备我会给你的，但在这之前，你得先完成全部的特训。',Speaker=811892,Action={actionid=867},}",
  [654357] = "{id=654357,Text='现在，带上这份成绩单，去找伊莱·雪耳博士吧。',Speaker=811892,Action={actionid=867},}",
  [654358] = "{id=654358,Text='请问……伊莱·雪耳博士在吗？',}",
  [654359] = "{id=654359,Voice='Npc/Eli_01',Text='喵~呜~我就是伊莱·雪耳！',Speaker=811889,ModelFace=3,ModelAct=0,BlackMask=1,}",
  [654360] = "{id=654360,Text='你好喵，[c][ffff00]命运之风[-][/c]~~',Speaker=811889,ModelFace=3,ModelAct=868,BlackMask=1,}",
  [654361] = "{id=654361,Text='会、会说话的猫咪！',Emoji=1,}",
  [654362] = "{id=654362,Text='不对哦~我是能够沟通自然的多兰族啦喵，和普通猫咪可不一样呢！',Speaker=811889,ModelFace=1,ModelAct=867,BlackMask=1,}",
  [654363] = "{id=654363,Text='你是来参加特训的吧？',Speaker=811889,Option='是的',ModelFace=1,ModelAct=868,BlackMask=1,}",
  [654364] = "{id=654364,Text='好哦喵~阿历克塞训练了你的战斗天赋，而我则要训练你的生存智慧！',Speaker=811889,ModelFace=1,ModelAct=867,BlackMask=1,}",
  [654365] = "{id=654365,Text='请从魔药田里采集两株薄荷草吧，切记不要采集成火药草喵~',Speaker=811889,ModelFace=4,ModelAct=868,BlackMask=1,}",
  [654366] = "{id=654366,Text='请问……伊莱·雪耳博士在吗？',}",
  [654367] = "{id=654367,Voice='Npc/Eli_01',Text='咪呜，在呢在呢~',Speaker=811889,ModelFace=3,ModelAct=867,BlackMask=1,}",
  [654368] = "{id=654368,Text='没想到[c][ffff00]命运之风[-][/c]也是多兰族呢，伊莱好开心喵！',Speaker=811889,ModelFace=3,ModelAct=868,BlackMask=1,}",
  [654369] = "{id=654369,Text='可爱的小猫猫，你叫什么名字呢？',Speaker=811889,Option='自我介绍',ModelFace=3,ModelAct=867,BlackMask=1,}",
  [654370] = "{id=654370,Text='[c][ffff00][PlayerName][-][/c]吗？真是个好名字呢喵。你是来参加特训的吧？',Speaker=811889,Option='是的',ModelFace=1,ModelAct=868,BlackMask=1,}",
  [654371] = "{id=654371,Text='好的喵~让我来教你辨识和采集植物吧，咪呜！',Speaker=811889,ModelFace=1,ModelAct=867,BlackMask=1,}",
  [654372] = "{id=654372,Text='花田里长着两种不同的花朵，你要注意分辨它们的颜色，我只收[c][ffff00]白白的月光花[-][/c]哟~',Speaker=811889,ModelFace=4,ModelAct=868,BlackMask=1,}",
  [654373] = "{id=654373,Text='哈！烤小鸟！你还在啊~胆子很肥嘛！',Speaker=811921,Option='走开！',}",
  [654374] = "{id=654374,Text='走开啦！烦人的家伙！',Emoji=12,Action={actionid=11},}",
  [654375] = "{id=654375,Text='哈？这片森林明明是本大爷的地盘！谁允许你在这儿采花的！',Speaker=811921,}",
  [654376] = "{id=654376,Text='给我吃土去吧！',Speaker=811921,}",
  [654377] = "{id=654377,Text='采个月光花而已，你怎么弄成这个样子了喵！',Speaker=811889,Option='{克鲁鲁欺负我,0},{都怪克鲁鲁！,0}',ModelFace=8,ModelAct=869,BlackMask=1,}",
  [654378] = "{id=654378,Text='喵？又是克鲁鲁这个坏东西！',Speaker=811889,ModelFace=5,ModelAct=0,BlackMask=1,}",
  [654379] = "{id=654379,Text='[c][ffff00][PlayerName][-][/c]，你放心，我们会找机会教训它的。但首先，我得先处理你的伤势。',Speaker=811889,ModelFace=5,ModelAct=0,BlackMask=1,}",
  [654380] = "{id=654380,Text='听从我的指导治疗自己，痛痛就能飞走拉！',Speaker=811889,ModelFace=5,ModelAct=0,BlackMask=1,}",
  [654381] = "{id=654381,Text='咪呜，学得很快呢。现在我们可以继续训练啦~~',Speaker=811889,Option='好的',ModelFace=3,ModelAct=868,BlackMask=1,}",
  [654382] = "{id=654382,Text='看到那边可可爱爱的曼陀罗学士了吗？我需要你从它们身上收集一些学士帽！',Speaker=811889,ModelFace=1,ModelAct=0,BlackMask=1,}",
  [654383] = "{id=654383,Text='阿历克塞教会了你的自动战斗，可以在这里试一试哦！',Speaker=811889,Option='嗯嗯',ModelFace=1,ModelAct=0,BlackMask=1,}",
  [654384] = "{id=654384,Voice='Npc/Eli_02',Text='咪呜，确实是曼陀罗学士头上的帽子呢！',Speaker=811889,Emoji=17,}",
  [654385] = "{id=654385,Text='太棒了喵，这样你就把“全能初心者特训”的所有项目完成啦~',Speaker=811889,Action={actionid=868},}",
  [654386] = "{id=654386,Text='把这份成绩单交给希格德莉法，她知道该怎么做的喵。',Speaker=811889,}",
  [654387] = "{id=654387,Text='对了咪呜！我还有个[c][ffff00]蝴蝶翅膀[-][/c]要送给你。',Speaker=811889,Emoji=11,}",
  [654388] = "{id=654388,Text='蝴蝶翅膀是冒险中必不可少的道具~它可以帮助你快速回到卡普拉公司为你储存的地点~',Speaker=811889,}",
  [654389] = "{id=654389,Text='希格德莉法已经将你的储存点设置在了学院，可以试着用用看，咪呜！',Speaker=811889,}",
  [654390] = "{id=654390,Text='哇！你的成绩也太棒了吧！两位导师都给出A级评价呢。',Speaker=811888,ModelFace=6,ModelAct=868,BlackMask=1,}",
  [654391] = "{id=654391,Text='不过，我看你身上有些狼狈，是遇到什么意外了吗？',Speaker=811888,Option='{克鲁鲁……,0},{它好烦啊……,0}',ModelFace=8,ModelAct=867,BlackMask=1,}",
  [654392] = "{id=654392,Text='欸，你竟然遇到了克鲁鲁吗？！',Speaker=811888,ModelFace=8,ModelAct=868,BlackMask=1,}",
  [654393] = "{id=654393,Text='唔……它是原本盘踞在星泪森林的魔物啦，学院刚建成时没少给我添乱。后来我把它暴打了一顿，才变得老实下来。',Speaker=811888,ModelFace=8,ModelAct=867,BlackMask=1,}",
  [654394] = "{id=654394,Text='它找你麻烦了是不是？没关系，我一会儿就去教训它！',Speaker=811888,Option='{学院刚建成？,0},{你今年几岁……,0}',ModelFace=5,ModelAct=868,BlackMask=1,}",
  [654395] = "{id=654395,Voice='Npc/Sigrdrifa_05',Text='嗯？啊？你听错了吧，好孩子不要多问哦~~~',Speaker=811888,ModelFace=3,ModelAct=867,BlackMask=1,}",
  [654396] = "{id=654396,Text='好啦好啦，先不要管这些奇奇怪怪的事情，我们来领取特训的奖励吧~',Speaker=811888,ModelFace=3,ModelAct=868,BlackMask=1,}",
  [654397] = "{id=654397,Text='因为你在考试中表现优异，可以获得一份学霸特供的个性头饰。',Speaker=811888,ModelFace=1,ModelAct=867,BlackMask=1,}",
  [654398] = "{id=654398,Text='两种款式任你选择，让学长学姐给你介绍一下吧~',Speaker=811888,ModelFace=4,ModelAct=868,BlackMask=1,}",
  [654399] = "{id=654399,Text='我头顶上的蛋壳帽是用大嘴鸟的蛋壳做的，坚实耐用。',Speaker=811910,}",
  [654400] = "{id=654400,Text='戴上它，你就会拥有整座学院最“铁”的头。',Speaker=811910,Action={actionid=39},}",
  [654401] = "{id=654401,Text='波利帽也很可爱哦！粉粉嫩嫩、手感极佳。',Speaker=811911,}",
  [654402] = "{id=654402,Text='而且戴上它的人都会受到波利的祝福哦~',Speaker=811911,Action={actionid=32},}",
  [654403] = "{id=654403,Text='听我的，不会错！',Speaker=811910,}",
  [654404] = "{id=654404,Text='选我嘛，选我嘛！',Speaker=811911,}",
  [654405] = "{id=654405,Text='选我！',Speaker=811910,}",
  [654406] = "{id=654406,Text='选我！',Speaker=811911,}",
  [654407] = "{id=654407,Text='好啦好啦，都别吵啦。重要的不是小学弟自己的选择吗？',Speaker=811888,Emoji=40,Action={actionid=206},}",
  [654408] = "{id=654408,Text='[c][ffff00][PlayerName][-][/c]，你中意哪一款头饰呢？为了学院的爱与和平，请你尽快做出决定吧。',Speaker=811888,}",
  [654409] = "{id=654409,Text='蛋壳帽是勇士的浪漫，和我一样成为“蛋壳帽党”吧！',Speaker=811910,Option='{好的 ,4},{再考虑考虑,3}',}",
  [654410] = "{id=654410,Text='好吧，你再考虑一下。',Speaker=811910,Emoji=25,}",
  [654411] = "{id=654411,Text='哈，有眼光！',Speaker=811910,Emoji=20,Action={actionid=39},}",
  [654412] = "{id=654412,Text='把这份图纸和所需的素材一起交给[c][ffff00]微笑小姐[-][/c]，就可以制作头饰了。',Speaker=811910,}",
  [654413] = "{id=654413,Text='波利帽最最可爱了！和我一起加入“波利万岁神教”吧~',Speaker=811911,Option='{好的 ,4},{再考虑考虑,3}',}",
  [654414] = "{id=654414,Text='诶！真的不选人家吗？',Speaker=811911,Emoji=24,}",
  [654415] = "{id=654415,Text='我就知道你会选我的！粉嫩波利万岁！',Speaker=811911,Action={actionid=39},}",
  [654416] = "{id=654416,Text='把这份图纸和所需的素材一起交给[c][ffff00]微笑小姐[-][/c]，就可以制作头饰了。',Speaker=811911,}",
  [654417] = "{id=654417,Text='哇哦，这个头饰很衬你呢！',Speaker=811888,Emoji=17,Action={actionid=39},}",
  [654418] = "{id=654418,Text='顺便再拍一张照片，记录下你初入学的青葱岁月吧！',Speaker=811888,}",
  [654419] = "{id=654419,Text='[c][ffff00][PlayerName][-][/c]，你回来啦！特训的结果怎么样呢？',Speaker=811888,ModelFace=1,ModelAct=867,BlackMask=1,}",
  [654420] = "{id=654420,Text='好啦好啦，都别吵啦。重要的不是小学妹自己的选择吗？',Speaker=811888,Emoji=40,Action={actionid=206},}",
  [654426] = "{id=654426,Text='好啦，特训完成了、头饰也制作过了，现在我们可以搞个大事情了！',Speaker=811888,ModelFace=1,ModelAct=868,BlackMask=1,}",
  [654428] = "{id=654428,Text='——作为命运之风，你的培养计划和其他人并不相同。',Speaker=811888,ModelFace=4,ModelAct=868,BlackMask=1,}",
  [654429] = "{id=654429,Text='学院为你准备了一个特殊的仪式，能让你接受[c][ffff00]女武神的指引[-][/c]！',Speaker=811888,Option='女武神的指引？',ModelFace=1,ModelAct=867,BlackMask=1,}",
  [654430] = "{id=654430,Text='女武神的指引能够给予你强大的力量，直接到达[c][ffff00]职业三转阶段[-][/c]！',Speaker=811888,ModelFace=1,ModelAct=868,BlackMask=1,}",
  [654431] = "{id=654431,Text='你想现在就使用这个机会、实现快速成长；还是不使用，依靠自己脚踏实地、慢慢冒险升级呢？',Speaker=811888,ModelFace=1,ModelAct=867,BlackMask=1,}",
  [654432] = "{id=654432,Text='[c][ffff00]你想现在就进行仪式，接受女武神的指引，开启你精彩的冒险旅程吗？[-][/c]',Speaker=811888,Option='{考虑考虑,20},{[c][ffff00]是的[-][/c],13},{我拒绝,3}',ModelFace=1,ModelAct=868,BlackMask=1,}",
  [654433] = "{id=654433,Text='天呐！你居然要放弃如此神圣的仪式！错过这次的机会，你的冒险旅程会变得[c][ffff00]无比艰难[-][/c]！你确定要这样做吗？',Speaker=811888,Option='{确定,7},{[c][ffff00]我改变主意了[-][/c],2}',ModelFace=7,ModelAct=867,BlackMask=1,}",
  [654434] = "{id=654434,Text='好的，没想到你更希望依靠自己的能力成长呢~',Speaker=811888,}",
  [654435] = "{id=654435,Text='那么请前往普隆德拉的南门吧！',Speaker=811888,}",
  [654436] = "{id=654436,Text='那么请前往白云深处的罗扎纳吧！',Speaker=811888,}",
  [654437] = "{id=654437,Text='总有一天，我会从他人口中再听到你的名字。那时的你，一定成为了不起的冒险者啦！',Speaker=811888,}",
  [654438] = "{id=654438,Text='当然，如果你希望使用[c][ffff00]快速三转机会[-][/c]的机会，也可以回来找我。我会一直在这里等着你的。',Speaker=811888,}",
  [654439] = "{id=654439,Text='现在就要离开学院吗？让我送你一程吧~',Speaker=811888,Option='{立即出发,10},{再等一等,20}',}",
  [654440] = "{id=654440,Text='嗯嗯，你可以随时回来找我哦！',Speaker=811888,}",
  [654441] = "{id=654441,Text='如果使用，以后就[c][ffff00]没有第二次快速三转机会[-][/c]啦。确定要现在使用吗？',Speaker=811888,Option='{确定,13},{我改变主意了,20}',ModelFace=1,ModelAct=868,}",
  [654442] = "{id=654442,Text='好哦~你的选择我已经记录下来啦！等你接受了女武神的指引，就能呼啦一下变成超~~强~~~的冒险者了！',Speaker=811888,}",
  [654443] = "{id=654443,Text='不过首先，你要去初心殿堂选择自己的职业。会有一位[c][ffff00]神秘嘉宾[-][/c]从旁协助你哦！',Speaker=811888,}",
  [654444] = "{id=654444,Text='需要我把你直接传送到初心殿堂去吗？',Speaker=811888,Option='{现在出发,303},{一会儿再去,302}',}",
  [654445] = "{id=654445,Text='是想在学院里逛一逛吗？没问题，等你玩够了再来找我吧~',Speaker=811888,}",
  [654446] = "{id=654446,Text='已经准备好啦？那我们就出发吧~',Speaker=811888,}",
  [654447] = "{id=654447,Text='咕咕，回神啦回神啦，傻乎乎的冒险者！',Speaker=811914,}",
  [654448] = "{id=654448,Text='重新自我介绍一下：我是王立克里图拉的学院精灵，奥尔加·古埃·咕，负责指导初心者们选择自己的冒险职业。',Speaker=811914,}",
  [654449] = "{id=654449,Text='我手里的这份卷轴，是由普隆德拉冒险者协会与吉芬魔法塔联合出品的魔法问卷。',Speaker=811914,}",
  [654450] = "{id=654450,Text='用心做完之后，你就能了解自己最适合什么职业啦。快来试试看吧~',Speaker=811914,Option='好',}",
  [654451] = "{id=654451,Text='好吧。反正我已经等你那么久啦，也不多这么一会儿咕。',Speaker=811914,}",
  [654452] = "{id=654452,Text='咕咕，那我们就开始咯~',Speaker=811914,}",
  [654453] = "{id=654453,Text='咕咕，原来你适合这个职业啊。身位命运之风的你，一定可以成为了不起的[c][ffff00]符文骑士[-][/c]的！',Speaker=811914,}",
  [654454] = "{id=654454,Text='去找[c][ffff00]符文骑士[-][/c]的职业导师达尔克吧，他会带你去传承之间、接受女武神的指引哒！',Speaker=811914,}",
  [654455] = "{id=654455,Text='还有还有！！如果你实在想选择其他职业也没有问题，魔法问卷也只是参考而已。',Speaker=811914,}",
  [654456] = "{id=654456,Text='学院鼓励每一位冒险者自由发展，只要和对应的职业导师沟通，同样可以进行快速升级哦。',Speaker=811914,Option='知道了',}",
  [654457] = "{id=654457,Text='咕咕，去吧去吧，进阶成为职业的冒险家吧 ！',Speaker=811914,}",
  [654458] = "{id=654458,Text='我说，你们为什么非要跟过来啊！！！就让这件事安安静静地过去不好吗？',Speaker=811934,Emoji=24,Action={actionid=206},}",
  [654459] = "{id=654459,Text='咪呜~大家都很期待嘛！',Speaker=811944,Emoji=17,}",
  [654460] = "{id=654460,Text='而且、而且……感觉会很有趣喵！',Speaker=811944,}",
  [654461] = "{id=654461,Text='咕咕，阿历克塞，别扭捏了！',Speaker=811915,Action={actionid=214},}",
  [654462] = "{id=654462,Text='不就是一套衣服嘛，大不了再找希格德莉法补一套！咕~',Speaker=811915,}",
  [654463] = "{id=654463,Text='愿赌服输啊，臭教官！',Speaker=811946,}",
  [654464] = "{id=654464,Text='什么热闹？让我康康！',Speaker=811945,}",
  [654465] = "{id=654465,Text='教官，是男人就快脱啊！',Speaker=811947,}",
  [654466] = "{id=654466,Text='啊啊啊啊——！脱就脱，你们真以为我不敢吗！',Speaker=811934,}",
  [654467] = "{id=654467,Text='就算没有护甲！我也是最英勇的战士！ （间隔一段时间，循环播放）',Speaker=811938,}",
  [654468] = "{id=654468,Text='哇！教官还是那么自信！（间隔一段时间，循环播放）',Speaker=811946,}",
  [654469] = "{id=654469,Text='真男人阿历克塞！（间隔一段时间，循环播放）',Speaker=811947,}",
  [654470] = "{id=654470,Text='噫，辣眼睛！（间隔一段时间，循环播放）',Speaker=811887,}",
  [654471] = "{id=654471,Text='咕咕，脱得真干净。甚至还打了个包~',Speaker=811950,}",
  [654472] = "{id=654472,Text='[c][ffff00][PlayerName][-][/c]，快把护甲捡起来喵！',Speaker=811944,}",
  [654473] = "{id=654473,Text='获得合适的装备，要及时穿戴喵~',Speaker=811944,}",
  [654474] = "{id=654474,Text='哼哼，护甲是不是很合身？哼，怎么会不合身呢！',Speaker=811938,}",
  [654475] = "{id=654475,Text='如果这样你都获得不了勇者印记的话，我可饶不了你！',Speaker=811938,Option='勇者印记？',}",
  [654476] = "{id=654476,Text='哦豁，你居然没听说？',Speaker=811938,}",
  [654477] = "{id=654477,Text='相传，女武神战胜克鲁鲁后，在它身上留下了一个印记和一句话。',Speaker=811938,}",
  [654478] = "{id=654478,Text='“真正的勇士以胜利证明自己的实力，我将赐予他祝福，带着荣光离去。”',Speaker=811938,Option='什么意思？',}",
  [654479] = "{id=654479,Text='意思是，当克鲁鲁再次被击败后，印记便会激活，女武神将再次出现赐予勇者祝福。',Speaker=811938,}",
  [654480] = "{id=654480,Text='怎么样？想不想去试试？克鲁鲁之前没少给你惹麻烦吧？',Speaker=811938,}",
  [654481] = "{id=654481,Text='想不想获得勇者印记，顺便给那个烦人的东西一点教训？',Speaker=811938,}",
  [654482] = "{id=654482,Text='【[c][ffff00]以下为技能教学副本，请选择是否接受[-][/c]。】',Speaker=811938,Option='{是,17},{否,16}',}",
  [654483] = "{id=654483,Text='算了吧……学院外的使命更重要。',}",
  [654484] = "{id=654484,Text='在冒险中解决危机，也可以证明自己的实力！穿着我的护甲！你可不能给我丢人！',Speaker=811938,}",
  [654485] = "{id=654485,Text='离校前，希格德莉法还有些事情要交待你。',Speaker=811938,}",
  [654486] = "{id=654486,Text='需要我直接送你过去吗？',Speaker=811938,}",
  [654487] = "{id=654487,Text='好的喵，一定要记得去哦~',Speaker=811938,}",
  [654488] = "{id=654488,Text='求之不得！',Emoji=5,Action={actionid=9},}",
  [654489] = "{id=654489,Text='哦豁！就是这样！给克鲁鲁一个教训！',Speaker=811938,}",
  [654490] = "{id=654490,Text='战斗中遇到困难，也不要害怕！你穿着可是我的护甲！',Speaker=811938,}",
  [654491] = "{id=654491,Text='做好准备的话，就准备出发吧！',Speaker=811938,Option='{没问题了,19},{再等一下,18}',Emoji=17,Action={actionid=868},}",
  [654492] = "{id=654492,Text='还有还有！！如果你实在想选择其他职业也没有问题，魔法问卷也只是参考而已。',Speaker=811915,}",
  [654493] = "{id=654493,Text='学院鼓励每一位冒险者自由发展，只要和对应的职业导师沟通，同样可以进行快速升级哦。',Speaker=811915,Option='知道了',}",
  [654494] = "{id=654494,Text='咕咕，去吧去吧，进阶成为职业的冒险家吧 ！',Speaker=811915,}",
  [654495] = "{id=654495,Text='你已经拥有该系的三转职业了，请把这次机会留给[c][ffff00]其他职业[-][/c]吧。',Speaker=816567,Option='我知道了',}",
  [654496] = "{id=654496,Text='好，那我现在就为你转职成影狼。',Speaker=816567,}",
  [654497] = "{id=654497,Text='好，那我现在就为你转职成胧。',Speaker=816567,}",
  [654498] = "{id=654498,Text='骤然获得这么多力量，你是不是感到有些迷茫呢？',Speaker=816567,}",
  [654499] = "{id=654499,Text='不要害怕，我现在就帮你梳理一下思路。',Speaker=816567,}",
  [654500] = "{id=654500,Text='首先，你要搞清楚，忍者一共有三种流派：',Speaker=816567,}",
  [654501] = "{id=654501,Text='[c][ffff00]流刃流派[-][/c]的忍者使用秘传剑术“流刃”斩杀敌人，致命的“无空斩”杀人于无形，还能召唤潜伏在阴影中的武士携力攻击。',Speaker=816567,}",
  [654502] = "{id=654502,Text='[c][ffff00]风魔流派[-][/c]的忍者通过投掷风魔手里剑作战，与敌人保持距离进行远程攻击，在保证自身安全的同时进行稳定的输出。',Speaker=816567,}",
  [654503] = "{id=654503,Text='[c][ffff00]忍法流派[-][/c]的忍者使用“忍法”与“通灵术”作战，擅长群攻，可以造成多样的属性魔法伤害。',Speaker=816567,}",
  [654504] = "{id=654504,Text='[c][ffff00][PlayerName][-][/c]，你想选择哪一种流派发展呢？',Speaker=816567,Option='{流刃流派,1000},{风魔流派,2000},{忍法流派,3000},{我考虑考虑,1}',}",
  [654505] = "{id=654505,Text='好，这是你的流派专属武器，记得要装备上哦。',Speaker=816567,}",
  [654506] = "{id=654506,Text='另外，你也要记住：职业流派之间除了武器不同，所需要的素质点也不尽相同。',Speaker=816567,}",
  [654507] = "{id=654507,Text='因为你是新人，这一次素质点我替你分配好了。',Speaker=816567,}",
  [654508] = "{id=654508,Text='以后冒险升级、获得新素质点后，也不要忘记合理分配它们。',Speaker=816567,}",
  [654509] = "{id=654509,Text='好了，教学应该快结束了。',Speaker=816567,Emoji=26,}",
  [654510] = "{id=654510,Text='经过我的教导，你已经很有影狼的样子了。',Speaker=816567,}",
  [654511] = "{id=654511,Text='经过我的教导，你已经很有胧的样子了。',Speaker=816567,}",
  [654512] = "{id=654512,Text='只差为你找一身合适的装备。',Speaker=816567,Option='{说到装备……,0},{我想起来了！,0}',}",
  [654513] = "{id=654513,Text='哦~阿历克塞和你打赌，把那身“英灵护甲”输给你了？',Speaker=816567,Emoji=11,}",
  [654514] = "{id=654514,Text='一向狂妄又骄傲的男人，终究是栽了啊~',Speaker=816567,Emoji=17,}",
  [654515] = "{id=654515,Text='英灵护甲是女武神赐下的神装。不但性能强大，还会根据使用者的职业自动变化。',Speaker=816567,}",
  [654516] = "{id=654516,Text='你是个幸运的小家伙，去找阿历克塞，让他履行自己的赌约吧~',Speaker=816567,Option='好',}",
  [654517] = "{id=654517,Text='将“英灵护甲”拿到手，你就能获得一身再合适不过的装备了！',Speaker=816567,}",
  [654518] = "{id=654518,Text='所有装备都穿戴好了吗？尤其是我的护甲！准备出发了！',Speaker=811938,Option='{没问题了,29},{再等一下,28}',Emoji=17,Action={actionid=868},}",
  [654519] = "{id=654519,Text='【[c][ffff00]以下为技能教学副本，请选择是否接受[-][/c]。】',Speaker=811938,Option='{是,27},{否,26}',}",
  [654520] = "{id=654520,Text='所有装备都穿戴好了吗？尤其是我的护甲！准备出发了！',Speaker=811938,Option='{没问题了,119},{再等一下,118}',Emoji=17,Action={actionid=868},}",
  [654521] = "{id=654521,Text='所有装备都穿戴好了吗？尤其是我的护甲！准备出发了！',Speaker=811938,Option='{没问题了,129},{再等一下,128}',Emoji=17,Action={actionid=868},}",
  [654522] = "{id=654522,Text='【[c][ffff00]以下为技能教学副本，请选择是否接受[-][/c]。】',Speaker=811938,Option='{是,37},{否,36}',}",
  [654523] = "{id=654523,Text='所有装备都穿戴好了吗？尤其是我的护甲！准备出发了！',Speaker=811938,Option='{没问题了,39},{再等一下,38}',Emoji=17,Action={actionid=868},}",
  [654524] = "{id=654524,Text='所有装备都穿戴好了吗？尤其是我的护甲！准备出发了！',Speaker=811938,Option='{没问题了,139},{再等一下,138}',Emoji=17,Action={actionid=868},}",
  [654536] = "{id=654536,Text='对呀！罗扎纳的猫猫都会说话呀，咪呜！',Speaker=811889,Option='罗扎纳？',ModelFace=1,ModelAct=871,BlackMask=1,}",
  [654537] = "{id=654537,Text='那是我们多兰族的故乡，咪呜~有很多超级可爱的猫猫，还有各种好吃的甜点！',Speaker=811889,ModelFace=3,ModelAct=869,BlackMask=1,}",
  [654538] = "{id=654538,Text='比如脆脆的曲奇饼干、香香的巧克力饼、大大的冰淇淋蛋糕……',Speaker=811889,ModelFace=3,ModelAct=871,BlackMask=1,}",
  [654539] = "{id=654539,Text='哎呀呀，跑题啦跑题啦，差点忘了喵！',Speaker=811889,ModelFace=1,ModelAct=868,BlackMask=1,}",
  [654540] = "{id=654540,Text='你是来参加特训的吧？',Speaker=811889,Option='是的',ModelFace=1,ModelAct=867,BlackMask=1,}",
  [654541] = "{id=654541,Text='好的喵~让我来教你辨识和采集草药吧，咪呜！',Speaker=811889,ModelFace=1,ModelAct=871,BlackMask=1,}",
  [654542] = "{id=654542,Text='魔药田里长着两种不同的草药，你要注意分辨它们的颜色，我只收白白的月光花哟~',Speaker=811889,ModelFace=4,ModelAct=867,BlackMask=1,}",
  [654543] = "{id=654543,Text='怎么了怎么了！发生什么事了喵？',Speaker=811889,}",
  [654544] = "{id=654544,Text='咪、咪呜！！！',Speaker=811889,ModelFace=8,ModelAct=868,BlackMask=1,}",
  [654546] = "{id=654546,Text='现在，我也该和你说再见了。让我为你发布最后的指引吧。',Speaker=811951,}",
  [654547] = "{id=654547,Text='“命运选召的勇者，前往普隆德拉的金色泉水。',Speaker=811951,Action={actionid=38},}",
  [654548] = "{id=654548,Text='远方的龙之城正在等待着你，开启属于自己的传奇。”',Speaker=811951,}",
  [654549] = "{id=654549,Text='总有一天，我会从他人口中再听到你的名字。那时，必将是世人把你的事迹传唱。',Speaker=811951,}",
  [654550] = "{id=654550,Text='离开学院之前，记得找那边的毕业指导员：卡拉扬，领取一本名为[c][ffff00]《冒险：从入门到精通》[-][/c]的手册。',Speaker=811951,Emoji=7,}",
  [654551] = "{id=654551,Text='它不仅能为你解答冒险中的疑问，还为你罗列出一系列能使你变强的挑战目标。',Speaker=811951,}",
  [654552] = "{id=654552,Text='达成手册中的全部目标后，你可以将它返还回学院，会有人为你兑换奖励。',Speaker=811951,Option='明白了',}",
  [654553] = "{id=654553,Text='想启程前往普隆德拉时，可以告诉我一声。',Speaker=811951,}",
  [654554] = "{id=654554,Text='我会指引你如何前往普隆德拉。',Speaker=811951,}",
  [654555] = "{id=654555,Text='暂时再见了，[c][ffff00][PlayerName][-][/c]。',Speaker=811951,Option='再见，莉法！',Emoji=17,}",
  [654556] = "{id=654556,Text='呀 ，找到啦找到啦~入学指南上写着：',Speaker=811888,ModelFace=6,ModelAct=0,}",
  [654557] = "{id=654557,Text='“如果命运之风拒绝参加特训，那就随他去吧。反正生活的毒打，也能教会他成长。”',Speaker=811888,ModelFace=3,ModelAct=0,}",
  [654558] = "{id=654558,Text='既然如此，我们就开始下一阶段吧。现在你的任务，是制作个性头饰。',Speaker=811888,ModelFace=1,ModelAct=868,}",
  [654559] = "{id=654559,Text='两位学长学姐已经迫不及待地想为你推荐样式了，快来见见他们吧。',Speaker=811888,ModelFace=1,ModelAct=867,}",
  [654560] = "{id=654560,Text='你的身体强度已经不能再承受这个进阶仪式了。【[c][ffff00]该账号已使用过一次快速升级的机会。[-][/c]】',Speaker=811888,}",
  [654561] = "{id=654561,Text='离开学院前！先去找那边的毕业指导员：卡拉扬把[c][ffff00]《冒险：从入门到精通》[-][/c]的手册领取了吧。',Speaker=811951,Option='好的',}",
  [654564] = "{id=654564,Text='号外号外，王立克里图拉学院又开始招新了，诚邀各位新老冒险者入学。',Speaker=811955,Option='克里图拉学院？',}",
  [654565] = "{id=654565,Text='容我向你介绍一下：王立克里图拉学院，是一所由卢恩王室创立、致力于帮助冒险者成长的学院。',Speaker=811955,}",
  [654566] = "{id=654566,Text='你看上去很有经验，但某些职业还有提高的空间吧？',Speaker=811955,Action={actionid=34},}",
  [654567] = "{id=654567,Text='学院新开设了“速成进阶班”，能给予你一次[c][ffff00]快速三转[-][/c]的机会。有兴趣报名入学吗？',Speaker=811955,Option='{知道了,3},{快速三转？,4}',}",
  [654568] = "{id=654568,Text='在米德加尔特大陆，大多数冒险者的职业可分为一转、二转、进阶二转和三转等阶段。',Speaker=811955,}",
  [654569] = "{id=654569,Text='每一次职业进阶，可以解锁更多强力的技能。',Speaker=811955,}",
  [654570] = "{id=654570,Text='快速三转能帮你省去辛苦升级的功夫，[c][ffff00]直接到达三转阶段[-][/c]。',Speaker=811955,}",
  [654571] = "{id=654571,Text='怎么样，有兴趣报名入学吗？',Speaker=811955,}",
  [654572] = "{id=654572,Text='【学院任务中，玩家可选择是否使用[c][ffff00]快速三转[-][/c]机会。使用后，[c][ffff00]同一账号下其他角色再无快速三转机会[-][/c]，也无法体验完整学院剧情。】',Speaker=811955,Option='{我想入学,7},{再等一等,6}',}",
  [654573] = "{id=654573,Text='没问题。等你有空了，再做决定也不迟。',Speaker=811955,}",
  [654574] = "{id=654574,Text='好的，那么我就将你的姓名录入本届新生名单了。',Speaker=811955,}",
  [654575] = "{id=654575,Text='你可以搭乘马车前往学院。',Speaker=811955,}",
  [654576] = "{id=654576,Text='要前往王立克里图拉学院吗？',Speaker=811956,Option='{立刻前往,10},{再等等,9}',}",
  [654577] = "{id=654577,Text='没问题。我会一直在这里等您的。',Speaker=811956,}",
  [654578] = "{id=654578,Text='入学的新生们，请到我这里来！',Speaker=811888,}",
  [654579] = "{id=654579,Voice='Npc/Sigrdrifa_04',Text='[c][ffff00][PlayerName][-][/c]~欢迎来到王立克里图拉学院！',Speaker=811888,ModelFace=3,ModelAct=868,Emoji=17,}",
  [654580] = "{id=654580,Text='我是你的接引人希格德莉法，你可以叫我莉法。',Speaker=811888,ModelFace=3,ModelAct=867,}",
  [654581] = "{id=654581,Text='你是来参加“速成进阶班”的，是吗？',Speaker=811888,Option='是的',ModelFace=1,ModelAct=868,}",
  [654582] = "{id=654582,Text='好哒，我了解啦~',Speaker=811888,ModelFace=1,ModelAct=867,}",
  [654583] = "{id=654583,Text='不过在进阶前，先听我简单介绍一下学院吧！',Speaker=811888,ModelFace=1,ModelAct=868,}",
  [654584] = "{id=654584,Text='就当重温校园生活、追忆青葱岁月~',Speaker=811888,ModelFace=4,ModelAct=867,}",
  [654585] = "{id=654585,Text='怎么样，学院是个很美的地方吧~闲暇之余可以多来走动哦！',Speaker=811888,ModelFace=1,ModelAct=868,}",
  [654586] = "{id=654586,Text='对上了年纪的人来说，呼吸新鲜空气、接触可爱的年轻人，有利于保持身心健康！',Speaker=811888,Option='{我不老！！！,3},{你很有经验？,4}',ModelFace=1,ModelAct=867,}",
  [654587] = "{id=654587,Text='啊哈哈哈，无意冒犯~我只是在分享过来人的经验罢了。',Speaker=811888,ModelFace=3,ModelAct=868,}",
  [654588] = "{id=654588,Text='咦，你是在暗示我上了年纪吗？哈哈哈，怎么会呢，人家可是学院第一美少女！',Speaker=811888,ModelFace=5,ModelAct=867,}",
  [654589] = "{id=654589,Text='好了好了，回到正题。',Speaker=811888,ModelFace=1,ModelAct=868,}",
  [654590] = "{id=654590,Text='你还记得吧——“速成进阶班”能帮你达成快速三转。但[c][ffff00]每个账号只有一次机会[-][/c]。',Speaker=811888,ModelFace=1,ModelAct=867,}",
  [654591] = "{id=654591,Text='你确定现在就用掉快速三转机会，以后也不后悔吗？',Speaker=811888,Option='{确定,3},{我想留到以后,4}',ModelFace=1,ModelAct=868,}",
  [654592] = "{id=654592,Text='没问题。毕竟只有一次机会，用掉可就没了。',Speaker=811888,ModelFace=1,ModelAct=867,}",
  [654593] = "{id=654593,Text='等你决定要快速三转后，再来找我对话吧。我会一直在学院等着你的。',Speaker=811888,ModelFace=1,ModelAct=868,}",
  [654594] = "{id=654594,Text='唔……但你并不满足使用条件呢！',Speaker=811888,ModelFace=1,ModelAct=867,}",
  [654595] = "{id=654595,Text='你当前的职业已经三转，学院无法提供你帮助。换一个职业再来找我吧~',Speaker=811888,ModelFace=3,ModelAct=868,}",
  [654596] = "{id=654596,Text='哇，真爽快！不过你确定要以当前职业[c][ffff00]快速三转[-][/c]吗？',Speaker=811888,ModelFace=1,ModelAct=867,}",
  [654597] = "{id=654597,Text='如果有其他想法，一定要切换职业，再找相应的导师进行升级。',Speaker=811888,Option='知道了',ModelFace=1,ModelAct=868,}",
  [654598] = "{id=654598,Text='没错~接受女武神的指引就可以[c][ffff00]快速三转[-][/c]哦！',Speaker=811888,ModelFace=1,ModelAct=867,BlackMask=1,}",
  [654599] = "{id=654599,Text='在米德加尔特大陆，大多数冒险者的职业可分为一转、二转、进阶二转和三转等阶段。',Speaker=811888,ModelFace=1,ModelAct=868,BlackMask=1,}",
  [654600] = "{id=654600,Text='每一次职业进阶，可以解锁更多强力的技能。',Speaker=811888,ModelFace=1,ModelAct=867,BlackMask=1,}",
  [654601] = "{id=654601,Text='最后，我这儿还有一套专属的武器和职业装备要交给你。',Speaker=816567,}",
  [654602] = "{id=654602,Text='另外，你也要记住：职业流派之间除了武器不同，所需要的素质点也不尽相同。',Speaker=816567,}",
  [654603] = "{id=654603,Text='因为你是新人，这一次素质点我替你分配好了。',Speaker=816567,}",
  [654604] = "{id=654604,Text='以后冒险升级、获得新素质点后，也不要忘记合理分配它们。',Speaker=816567,}",
  [654605] = "{id=654605,Text='怎么样，新装备很不错吧？我能感觉到，你的身上涌动着力量和战意。',Speaker=816567,}",
  [654606] = "{id=654606,Text='说不定连“勇者印记”都能被你拿下呢！',Speaker=816567,Option='勇者印记？',}",
  [654607] = "{id=654607,Text='你是校外来的吧？难怪没听说过。',Speaker=816567,}",
  [654608] = "{id=654608,Text='很久以前，学院附近活跃着一只名为克鲁鲁的强大魔物。它经常肆意捣蛋、扰乱教学。',Speaker=816567,}",
  [654609] = "{id=654609,Text='守护学院的女武神看不下去，出手教训了它，并在它身上留下了一个印记和一句话。',Speaker=816567,}",
  [654610] = "{id=654610,Text='“真正的勇士，理当守护学院。击败魔物之人，将唤醒印记、获得我的祝福。”',Speaker=816567,}",
  [654611] = "{id=654611,Text='她希望用这种方式，鼓励学生和克鲁鲁战斗，并不断成长、变强。',Speaker=816567,Option='原来如此',}",
  [654612] = "{id=654612,Text='这些年来，很多人都试着挑战克鲁鲁，可惜到现在还没有人成功。',Speaker=816567,}",
  [654613] = "{id=654613,Text='但换做你的话，没准就能打败它了！',Speaker=816567,}",
  [654614] = "{id=654614,Text='[c][ffff00][PlayerName][-][/c]，有兴趣为守护学院出一份力吗？【[c][ffff00]以下为技能教学副本，请选择是否接受[-][/c]。】',Speaker=816567,Option='{是 ,1100},{否,1003}',}",
  [654615] = "{id=654615,Text='我还要更重要的事。',}",
  [654616] = "{id=654616,Text='嗯，可以理解。这个机会就留给你的学弟学妹们吧。',Speaker=816567,}",
  [654617] = "{id=654617,Text='现在，你可以找希格德莉法办理离校手续。',Speaker=816567,}",
  [654618] = "{id=654618,Text='需要我把你传送过去吗？',Speaker=816567,Option='{需要,1004},{不需要,1005}',}",
  [654619] = "{id=654619,Text='我想挑战克鲁鲁，获得“勇者印记”！',}",
  [654620] = "{id=654620,Text='哈哈，我就知道你不会拒绝的。',Speaker=816567,}",
  [654621] = "{id=654621,Text='克鲁鲁就在星泪森林的深处，我会用魔法将你传送过去的。',Speaker=816567,}",
  [654622] = "{id=654622,Text='武器和装备都穿戴好了吗？要出发咯？',Speaker=816567,Option='{没问题了,1102},{再等一下,1101}',}",
  [654623] = "{id=654623,Text='你居然已经顺利进阶了，速度可真快！不愧是我看好的人。',Speaker=811888,}",
  [654624] = "{id=654624,Text='作为你的接引人，我宣布——',Speaker=811888,}",
  [654625] = "{id=654625,Text='[c][ffff00][PlayerName][-][/c]，正式从学院毕业啦！',Speaker=811888,}",
  [654626] = "{id=654626,Text='往后的冒险中也要勇往直前、不断努力哦~',Speaker=811888,Option='我会的！',}",
  [654627] = "{id=654627,Text='还有还有~~离校之前，不要忘记找旁边的卡拉扬，领取毕业手册哦~',Speaker=811888,Option='嗯嗯！',}",
  [654628] = "{id=654628,Text='那么，我也没什么要交待啦。再见咯，冒险者！',Speaker=811888,Option='再见啦，莉法！',Emoji=4,Action={actionid=32},}",
  [654629] = "{id=654629,Text='武器和装备都穿戴好了吗？要出发咯？',Speaker=816567,Option='{没问题了,1104},{再等一下,1103}',}",
  [654630] = "{id=654630,Text='[c][ffff00][PlayerName][-][/c]，有兴趣为守护学院出一份力吗？【[c][ffff00]以下为技能教学副本，请选择是否接受[-][/c]。】',Speaker=816567,Option='{是 ,2100},{否,2003}',}",
  [654631] = "{id=654631,Text='需要我把你传送过去吗？',Speaker=816567,Option='{需要,2004},{不需要,2005}',}",
  [654632] = "{id=654632,Text='武器和装备都穿戴好了吗？要出发咯？',Speaker=816567,Option='{没问题了,2102},{再等一下,2101}',}",
  [654633] = "{id=654633,Text='武器和装备都穿戴好了吗？要出发咯？',Speaker=816567,Option='{没问题了,2104},{再等一下,2103}',}",
  [654634] = "{id=654634,Text='[c][ffff00][PlayerName][-][/c]，有兴趣为守护学院出一份力吗？【[c][ffff00]以下为技能教学副本，请选择是否接受[-][/c]。】',Speaker=816567,Option='{是 ,3100},{否,3003}',}",
  [654635] = "{id=654635,Text='需要我把你传送过去吗？',Speaker=816567,Option='{需要,3004},{不需要,3005}',}",
  [654636] = "{id=654636,Text='武器和装备都穿戴好了吗？要出发咯？',Speaker=816567,Option='{没问题了,3102},{再等一下,3101}',}",
  [654637] = "{id=654637,Text='武器和装备都穿戴好了吗？要出发咯？',Speaker=816567,Option='{没问题了,3104},{再等一下,3103}',}",
  [654638] = "{id=654638,Text='一口气传承到太多力量，你是不是感到有些混乱呢？',Speaker=816544,}",
  [654639] = "{id=654639,Text='我现在就帮你梳理力量、添加技能点。',Speaker=816544,}",
  [654640] = "{id=654640,Text='皇家卫士是守护团队的中坚力量，坚韧的盾牌与护甲能够抵御大量伤害，需要时他们会化身“团队之盾”为队友提供庇护。',Speaker=816544,}",
  [654641] = "{id=654641,Text='你是否已经了解了皇家卫士的职业定位？',Speaker=816544,Option='是的',}",
  [654642] = "{id=654642,Text='最后，我这儿还有一套专属的武器和职业装备要交给你。',Speaker=816544,}",
  [654643] = "{id=654643,Text='另外，你也要记住：职业流派之间除了武器不同，所需要的素质点也不尽相同。',Speaker=816544,}",
  [654644] = "{id=654644,Text='因为你是新人，这一次素质点我替你分配好了。',Speaker=816544,}",
  [654645] = "{id=654645,Text='以后冒险升级、获得新素质点后，也不要忘记合理分配它们。',Speaker=816544,}",
  [654646] = "{id=654646,Text='怎么样，新装备很不错吧？我能感觉到，你的身上涌动着力量和战意。',Speaker=816544,}",
  [654647] = "{id=654647,Text='说不定连“勇者印记”都能被你拿下呢！',Speaker=816544,Option='勇者印记？',}",
  [654648] = "{id=654648,Text='你是校外来的吧？难怪没听说过。',Speaker=816544,}",
  [654649] = "{id=654649,Text='很久以前，学院附近活跃着一只名为克鲁鲁的强大魔物。它经常肆意捣蛋、扰乱教学。',Speaker=816544,}",
  [654650] = "{id=654650,Text='守护学院的女武神看不下去，出手教训了它，并在它身上留下了一个印记和一句话。',Speaker=816544,}",
  [654651] = "{id=654651,Text='“真正的勇士，理当守护学院。击败魔物之人，将唤醒印记、获得我的祝福。”',Speaker=816544,}",
  [654652] = "{id=654652,Text='她希望用这种方式，鼓励学生和克鲁鲁战斗，并不断成长、变强。',Speaker=816544,Option='原来如此',}",
  [654653] = "{id=654653,Text='这些年来，很多人都试着挑战克鲁鲁，可惜到现在还没有人成功。',Speaker=816544,}",
  [654654] = "{id=654654,Text='但换做你的话，没准就能打败它了！',Speaker=816544,}",
  [654655] = "{id=654655,Text='[c][ffff00][PlayerName][-][/c]，有兴趣为守护学院出一份力吗？【[c][ffff00]以下为技能教学副本，请选择是否接受[-][/c]。】',Speaker=816544,Option='{是 ,1100},{否,1003}',}",
  [654656] = "{id=654656,Text='我还要更重要的事。',}",
  [654657] = "{id=654657,Text='嗯，可以理解。这个机会就留给你的学弟学妹们吧。',Speaker=816544,}",
  [654658] = "{id=654658,Text='现在，你可以找希格德莉法办理离校手续。',Speaker=816544,}",
  [654659] = "{id=654659,Text='需要我把你传送过去吗？',Speaker=816544,Option='{需要,1004},{不需要,1005}',}",
  [654660] = "{id=654660,Text='我想挑战克鲁鲁，获得“勇者印记”！',}",
  [654661] = "{id=654661,Text='哈哈，我就知道你不会拒绝的。',Speaker=816544,}",
  [654662] = "{id=654662,Text='克鲁鲁就在星泪森林的深处，我会用魔法将你传送过去的。',Speaker=816544,}",
  [654663] = "{id=654663,Text='武器和装备都穿戴好了吗？要出发咯？',Speaker=816544,Option='{没问题了,1102},{再等一下,1101}',}",
  [654664] = "{id=654664,Text='武器和装备都穿戴好了吗？要出发咯？',Speaker=816544,Option='{没问题了,1104},{再等一下,1103}',}",
  [654665] = "{id=654665,Text='好，这是你的专属武器，记得要装备上哦。',Speaker=816544,}",
  [654666] = "{id=654666,Text='可以，现在的你，已经很有皇家卫士的样子。',Speaker=816544,Emoji=26,}",
  [654667] = "{id=654667,Text='只是这身装备，未免……',Speaker=816544,Option='{说到装备…… ,0},{我想起来了！,0}',}",
  [654668] = "{id=654668,Text='阿历克塞和你打赌，把那身“英灵护甲”输给你了？',Speaker=816544,Emoji=15,}",
  [654669] = "{id=654669,Text='英灵护甲是女武神赐下的神装。不但性能强大，还会根据使用者的职业自动变化。',Speaker=816544,}",
  [654670] = "{id=654670,Text='用这么宝贵的东西打赌，真不知道阿历是怎么想的……',Speaker=816544,}",
  [654671] = "{id=654671,Text='不过，做人要守信用，他必须把这套护甲交给你！',Speaker=816544,}",
  [654672] = "{id=654672,Text='我送你去找他吧？',Speaker=816544,Option='好',}",
  [654673] = "{id=654673,Text='因为你是新人，这一次素质点我替你分配好了。',Speaker=816544,}",
  [654674] = "{id=654674,Text='以后冒险升级、获得新素质点后，也不要忘记合理分配它们。',Speaker=816544,}",
  [654675] = "{id=654675,Text='唉，我就知道，他迟早栽在乱打赌的毛病上。',Speaker=816544,Option='英灵护甲？',}",
  [654676] = "{id=654676,Text='骤然获得这么多力量，你是不是感到有些迷茫呢？',Speaker=816546,}"
}
